/** @responsibility Narrows values decoded from a wire, where the compiler's types have already been erased. */

/**
 * A value as it arrives from `JSON.parse`.
 *
 * Shared rather than provider-scoped: every wire this library reads is JSON,
 * and the readers below are how a provider module gets from a decoded blob to
 * its own declared shapes.
 */
export type JsonValue =
  | string
  | number
  | boolean
  | null
  | JsonValue[]
  | { readonly [key: string]: JsonValue }

/**
 * Why these exist at all.
 *
 * Everything past `JSON.parse` is `unknown` at runtime — TypeScript's types are
 * erased, so a declared shape is a *claim* about the bytes, not a check on
 * them. There are exactly three ways to bridge that: assert and hope, validate
 * with a schema library, or narrow. Asserting turns one malformed line into a
 * crash somewhere far away; a schema library performs these same checks with a
 * dependency and a per-line cost on the hottest path in the parser.
 *
 * So: narrow — but narrow *once*, here, behind names. Scattering `typeof`
 * through the mapper is the thing worth objecting to; a handful of named
 * readers used consistently is not. Each returns `null` for "not that shape",
 * so a caller uses `??` to state its fallback rather than branching.
 */

/** What a line that could not be decoded at all becomes. */
export interface JsonLineFailure {
  readonly ok: false
  readonly line: string
  readonly reason: string
}

export interface JsonLineSuccess {
  readonly ok: true
  /** An object with a string `type` — the most any decoder can claim before reading further. */
  readonly line: { readonly type: string; readonly [key: string]: JsonValue | undefined }
}

export type JsonLineResult = JsonLineSuccess | JsonLineFailure

/**
 * Decodes one line of a newline-delimited JSON stream.
 *
 * Shared by every provider because every provider's wire is this: a stream is
 * read for as long as a process runs, and one malformed line — a truncated
 * write, a stray log — must not end the transcript, so failure is returned
 * rather than thrown. Blank lines fail with an explicit reason so a caller
 * filters them knowingly rather than by accident.
 */
export function parseJsonLine(text: string): JsonLineResult {
  const trimmed = text.trim()
  if (trimmed.length === 0) return { ok: false, line: text, reason: "empty line" }

  let decoded: unknown
  try {
    decoded = JSON.parse(trimmed)
  } catch (error) {
    return { ok: false, line: text, reason: error instanceof Error ? error.message : "invalid JSON" }
  }

  if (decoded === null || typeof decoded !== "object" || Array.isArray(decoded)) {
    return { ok: false, line: text, reason: "line is not a JSON object" }
  }
  if (typeof (decoded as { type?: unknown }).type !== "string") {
    return { ok: false, line: text, reason: "line has no `type`" }
  }
  return { ok: true, line: decoded as JsonLineSuccess["line"] }
}

/** Decodes a whole capture, keeping failures in place. */
export function parseJsonLines(text: string): readonly JsonLineResult[] {
  return text
    .split("\n")
    .filter((line) => line.trim().length > 0)
    .map(parseJsonLine)
}

/** Trims a path to its last two segments, which is what identifies a file in a narrow row. */
export function shortenPath(path: string): string {
  const parts = path.split("/").filter(Boolean)
  return parts.length <= 2 ? path : `…/${parts.slice(-2).join("/")}`
}

/** The value as a string, or null. */
export function asString(value: JsonValue | undefined): string | null {
  return typeof value === "string" ? value : null
}

/** The value as a finite number, or null. Rejects NaN, which JSON cannot carry but a producer can still imply. */
export function asNumber(value: JsonValue | undefined): number | null {
  return typeof value === "number" && Number.isFinite(value) ? value : null
}

/** The value as a boolean, or null — distinct from `false`, which some flags mean. */
export function asBoolean(value: JsonValue | undefined): boolean | null {
  return typeof value === "boolean" ? value : null
}

/**
 * The value as a plain object, or an empty one.
 *
 * Empty rather than null because every caller wants to read a field from it and
 * `{}` reads a missing field as missing — the same answer an absent object
 * should give.
 */
export function asRecord(value: JsonValue | undefined): Record<string, JsonValue> {
  if (value === null || value === undefined || typeof value !== "object" || Array.isArray(value)) {
    return {}
  }
  return value as Record<string, JsonValue>
}

/**
 * The value as an object, or null when it is anything else — including absent.
 *
 * The strict counterpart of [`asRecord`]: use this where "no object here" and
 * "an object with nothing in it" must stay different answers. Usage is the
 * case that matters — an absent block means the line reported nothing, and
 * flattening it to `{}` turns every counter into a confident zero.
 */
export function asObject(value: JsonValue | undefined): Record<string, JsonValue> | null {
  if (value === null || value === undefined || typeof value !== "object" || Array.isArray(value)) {
    return null
  }
  return value as Record<string, JsonValue>
}

/** The value as an array, or an empty one, for the same reason. */
export function asArray(value: JsonValue | undefined): readonly JsonValue[] {
  return Array.isArray(value) ? value : []
}

/** The value as an array of strings, dropping anything that is not one. */
export function asStrings(value: JsonValue | undefined): readonly string[] {
  return asArray(value).filter((entry): entry is string => typeof entry === "string")
}

/**
 * The value if it is one of `allowed`, else null.
 *
 * The bridge from a wire's open vocabulary to a closed union: a status the
 * provider invents tomorrow is rejected here rather than widening a field the
 * rest of the code has already promised is one of a few things.
 */
export function asOneOf<T extends string>(
  value: JsonValue | undefined,
  allowed: readonly T[],
): T | null {
  const text = asString(value)
  return text !== null && (allowed as readonly string[]).includes(text) ? (text as T) : null
}

/** @responsibility Folds a flat agent event log into the turns, tool groups, delegated runs and pending asks a transcript draws. */

import type {
  AgentEvent,
  AgentPath,
  BlockRef,
  PlanStep,
  SessionInfo,
  ToolResult,
  Usage,
  WorkflowPhaseProgress,
} from "./events"
import { TranscriptBuilder } from "./builder"
import { pathKey } from "./events"
import type { AgentEventType } from "./events"

/** A run of consecutive same-tool calls, collapsed behind one row. */
export interface ToolGroup {
  readonly kind: "tool_group"
  readonly name: string
  readonly calls: readonly AgentEvent[]
  /** Distinct targets across the run — three edits to one file is one target, not three. */
  readonly targets: number
  /** The single target when the whole run hit one, so the row can name it instead of counting to one. */
  readonly target: string | null
  readonly key: string
}

/** Either a lone event or a collapsed run. */
export type WorkItem = AgentEvent | ToolGroup

export function isToolGroup(item: WorkItem): item is ToolGroup {
  return "kind" in item && item.kind === "tool_group"
}

/** One prompt-to-result span of the main conversation. */
export interface Turn {
  readonly key: string
  /** Absent for a transcript that starts mid-conversation, which every resumed session does. */
  readonly prompt: AgentEvent | null
  readonly work: readonly WorkItem[]
  readonly completed: AgentEvent | null
  /**
   * The turn's closing text. `result.result` is a verbatim copy of the last
   * `assistant_text`, so a view that draws both prints the answer twice; a turn
   * that ended without one falls back to that last message directly.
   */
  readonly finalText: string | null
  readonly toolCalls: number
  readonly usage: Usage | null
}

/** One delegated run — a subagent, a workflow, or a backgrounded shell. */
export interface DelegatedRun {
  /** The spawning tool call's id, which is what the envelope path correlates on. */
  readonly callId: string
  /** The harness's own handle. A *different* id from `callId`, and confusing the two fails silently. */
  readonly taskId: string | null
  readonly kind: "agent" | "workflow" | "bash" | "other"
  readonly label: string | null
  readonly description: string | null
  /**
   * The run's own transcript, where the provider named one.
   *
   * Only opencode does: it puts the child session id on the spawning call, and
   * `opencode export <id>` reads it. Null everywhere else, which is what tells
   * a surface whether "open this subagent" is an offer it can honour.
   */
  readonly transcriptId: string | null
  /** Latest progress line, rewritten per event, so it drives a live status row. */
  readonly status: string | null
  readonly lastTool: string | null
  readonly done: boolean
  readonly usage: Usage | null
  /**
   * The run's own events. A subagent reports these; a workflow reports none —
   * its window is `phases` instead, which is a different view rather than no
   * view.
   */
  readonly events: readonly AgentEvent[]
  /**
   * A workflow's phase-and-agent board, latest snapshot. Empty for every other
   * kind of run.
   */
  readonly phases: readonly WorkflowPhaseProgress[]
  /** The run's own plan, when it keeps one. A delegated agent's checklist is not the session's. */
  readonly plan: readonly PlanStep[]
  /** How deep this run sits. `1` is a subagent of the main thread. */
  readonly depth: number
  readonly path: AgentPath
}

export interface Transcript {
  /**
   * Bumped once per absorbed event.
   *
   * The collections below are append-only and keep their identity across
   * snapshots — copying a whole session's events per frame is the cost the
   * incremental fold exists to avoid — so this, not reference equality, is what
   * a consumer memoizes on.
   */
  readonly revision: number
  /** Main-thread events in `seq` order. Delegated work is filed into `runs`; its spawning call stays here. */
  readonly events: readonly AgentEvent[]
  readonly turns: readonly Turn[]
  readonly runs: readonly DelegatedRun[]
  readonly runByCallId: ReadonlyMap<string, DelegatedRun>
  readonly resultByCallId: ReadonlyMap<string, ToolResult>
  /** Calls a later event proved will never get a result, so their rows stop shimmering. */
  readonly abandonedCallIds: ReadonlySet<string>
  /** The agent's plan as last published. Latest wins. */
  readonly plan: readonly PlanStep[]
  readonly session: SessionInfo | null
  /** Every `init` in order — a resumed session contributes one per process, which is where a model change shows up. */
  readonly sessions: readonly SessionInfo[]
  readonly pendingAsks: readonly AgentEvent[]
  readonly usage: Usage | null
}

/**
 * Orders a log by `seq`, without copying it when it already is.
 *
 * A live log is appended to in `seq` order, so the sort is a copy and a sort of
 * the whole session on every fold — and a fold runs on every frame. Checking
 * order first is one linear pass that the common case pays instead of an
 * allocation proportional to the session's whole length.
 *
 * Out-of-order input is still handled: it is only *persisted* logs merged from
 * several sources that arrive shuffled, and those still sort.
 */
function inSeqOrder(source: readonly AgentEvent[]): readonly AgentEvent[] {
  for (let index = 1; index < source.length; index += 1) {
    if (source[index]!.seq < source[index - 1]!.seq) {
      return [...source].sort((a, b) => a.seq - b.seq)
    }
  }
  return source
}

/** How many consecutive same-tool calls collapse into one row. Any repeat groups, so a run reads the same at two calls or thirty. */
export const GROUP_MIN = 2

/**
 * Payload types that put something on screen. What a collapse reveals, and what
 * can break a tool run, is a function of this set.
 *
 * Exported so a host that folds its own way can ask the same question the
 * built-in fold asks, rather than maintaining a second copy of this set that
 * has to be kept in step — a rule nothing enforces and everything eventually
 * breaks.
 *
 * `plan_updated` and `file_edits` are deliberately absent: both draw in their
 * own surface rather than as a row in the work list — the plan in its panel, the
 * changed files as one summary at the end of the turn — so counting either
 * would both overstate a collapse and split a run of calls down the middle.
 */
export const RENDERS: ReadonlySet<AgentEventType> = new Set<AgentEventType>([
  "user_message",
  "assistant_text",
  "reasoning",
  "tool_call_started",
  "error",
  "context_compacted",
  "rate_limited",
  "permission_denied",
  "task_started",
])

export function rendersRow(item: WorkItem): boolean {
  return isToolGroup(item) || RENDERS.has(item.payload.type)
}

/**
 * Assembles one closed turn from work that is already grouped.
 *
 * Shared by both folds so they produce identical turns rather than merely
 * similar ones — and takes items rather than raw events so the incremental
 * fold can group as it goes instead of regrouping the whole turn per frame.
 */
export function assembleTurn(
  prompt: AgentEvent | null,
  items: readonly WorkItem[],
  toolCalls: number,
  completed: AgentEvent | null,
  lastText: string | null,
  index: number,
): Turn {
  const final =
    completed !== null && completed.payload.type === "turn_completed" && completed.payload.finalText !== null
      ? completed.payload.finalText
      : lastText

  // `finalText` repeats the turn's *last* message verbatim, so that one row is
  // dropped rather than printed twice. Only the last: an agent that says
  // "Done." mid-turn and again at the end has said two things, and removing
  // every row whose text matches would silently delete the first.
  let body = items
  if (final !== null) {
    const duplicate = lastIndex(items, (item) => isSameText(item, final))
    if (duplicate !== -1) body = [...items.slice(0, duplicate), ...items.slice(duplicate + 1)]
  }

  return {
    // Keyed on the first thing in the turn, which is stable from the turn's
    // first render: keying on `completed` would remount the whole turn — losing
    // scroll and focus — at the moment it finishes.
    key: `turn:${prompt?.id ?? firstId(items) ?? completed?.id ?? index}`,
    prompt,
    work: body,
    completed,
    finalText: final,
    toolCalls,
    usage: completed !== null && completed.payload.type === "turn_completed" ? completed.payload.usage : null,
  }
}

function isSameText(item: WorkItem, text: string): boolean {
  return !isToolGroup(item) && item.payload.type === "assistant_text" && item.payload.text.trim() === text.trim()
}

function lastIndex(items: readonly WorkItem[], match: (item: WorkItem) => boolean): number {
  for (let index = items.length - 1; index >= 0; index -= 1) if (match(items[index]!)) return index
  return -1
}

function firstId(items: readonly WorkItem[]): string | null {
  const first = items[0]
  if (first === undefined) return null
  return isToolGroup(first) ? first.key : first.id
}

/** Collapses one run of consecutive same-tool calls into a group, or leaves it as rows if it is too short. */
export function collapseRun(run: readonly AgentEvent[]): readonly WorkItem[] {
  if (run.length < GROUP_MIN) return run
  const targets = new Set(run.map(titleOf).filter((title): title is string => title !== null))
  const first = run[0]!
  return [
    {
      kind: "tool_group",
      name: first.payload.type === "tool_call_started" ? first.payload.name : "",
      calls: run,
      targets: targets.size === 0 ? run.length : targets.size,
      target: targets.size === 1 ? [...targets][0]! : null,
      key: `group:${first.id}`,
    },
  ]
}

function titleOf(event: AgentEvent): string | null {
  return event.payload.type === "tool_call_started" ? event.payload.title : null
}

/** Collapses runs of consecutive same-tool calls, breaking on any other rendered row. */
export function groupTools(work: readonly AgentEvent[]): readonly WorkItem[] {
  const items: WorkItem[] = []
  let run: AgentEvent[] = []

  const flush = () => {
    if (run.length === 0) return
    items.push(...collapseRun(run))
    run = []
  }

  for (const event of work) {
    if (event.payload.type === "tool_call_started") {
      const name = event.payload.name
      const openName = run[0]?.payload.type === "tool_call_started" ? run[0].payload.name : null
      if (openName !== null && openName !== name) flush()
      run.push(event)
      continue
    }
    // Only a row the reader can see breaks a run. An invisible event between
    // two identical calls would otherwise split the group for no visible cause.
    if (rendersRow(event)) flush()
    items.push(event)
  }
  flush()
  return items
}

/**
 * Folds a whole log in one pass.
 *
 * Implemented *as* the incremental fold rather than beside it. Two
 * implementations of the same rules, kept in agreement by tests, drift the
 * first time someone patches one — and the divergence shows up as a live
 * session disagreeing with the same session reloaded, which is the hardest
 * class of bug to see. The only thing this adds is tolerance for a log that
 * arrives out of order, which a persisted log merged from several sources can.
 */
export function buildTranscript(
  source: readonly AgentEvent[],
  options: { readonly live?: boolean; readonly liveTaskIds?: ReadonlySet<string> } = {},
): Transcript {
  const builder = new TranscriptBuilder()
  builder.push(inSeqOrder(source))
  return builder.snapshot(options)
}

/** Live preview text accumulated from deltas, keyed by block. */
export type DeltaBuffers = ReadonlyMap<string, string>

function blockKey(block: BlockRef): string {
  return `${block.messageId}#${block.index}`
}

/**
 * Accumulates delta previews.
 *
 * Deltas are a preview and the committed event supersedes them, so a consumer
 * reads a buffer only while no committed event exists for that block. Absent
 * deltas are ordinary — a delegated run streams none — so a view built on this
 * must render correctly with an empty map.
 *
 * Pass `into` with only the newly arrived events to accumulate incrementally: a
 * live session appends, and rescanning the whole log per frame to rebuild
 * strings that only ever grow is the difference between linear and quadratic
 * over a session's life. Omit it for a one-shot read of a persisted log.
 */
export function applyDeltas(
  events: readonly AgentEvent[],
  into?: Map<string, string>,
): DeltaBuffers {
  const buffers = into ?? new Map<string, string>()
  for (const event of events) {
    const payload = event.payload
    if (payload.type !== "delta") continue
    if (payload.delta === "text") {
      buffers.set(blockKey(payload.block), (buffers.get(blockKey(payload.block)) ?? "") + payload.text)
    }
    if (payload.delta === "input") {
      buffers.set(blockKey(payload.block), (buffers.get(blockKey(payload.block)) ?? "") + payload.partialJson)
    }
  }
  return buffers
}

/** Reads one block's preview, if any has accumulated. */
export function previewOf(buffers: DeltaBuffers, block: BlockRef | null): string | null {
  return block === null ? null : (buffers.get(blockKey(block)) ?? null)
}

/** A stable React key for a run. */
export function runKey(run: DelegatedRun): string {
  return `run:${pathKey(run.path)}`
}

/**
 * Whether the agent is compacting its context *right now*.
 *
 * The boundary event only lands once the summary has been written, which took
 * 17 to 41 seconds across the captures — far too long for a surface to sit
 * looking idle. The status line says `compacting` as the work starts, so this
 * is read from the stream rather than guessed at, and any later status (or the
 * boundary itself) retires it.
 *
 * Derived here rather than in each consumer: "is it busy" is a question about
 * the stream, and two surfaces answering it differently would disagree about
 * the same session.
 */
export function isCompacting(events: readonly AgentEvent[]): boolean {
  let compacting = false
  for (const event of events) {
    if (event.payload.type === "context_compacted") compacting = false
    else if (event.payload.type === "status_changed") compacting = event.payload.status === "compacting"
  }
  return compacting
}

/** @responsibility Folds a live event log incrementally, so a running session costs work proportional to what arrived rather than to its whole length. */

import type { AgentEvent, AgentPath, PlanStep, SessionInfo, ToolResult, Usage } from "./events"
import { pathKey } from "./events"
import type { DelegatedRun, Transcript, Turn, WorkItem } from "./transcript"
import { assembleTurn, collapseRun, rendersRow } from "./transcript"

const EMPTY_TASKS: ReadonlySet<string> = new Set()

interface MutableRun {
  callId: string
  taskId: string | null
  kind: DelegatedRun["kind"]
  label: string | null
  description: string | null
  transcriptId: string | null
  status: string | null
  lastTool: string | null
  done: boolean
  usage: Usage | null
  events: AgentEvent[]
  plan: readonly PlanStep[]
  phases: DelegatedRun["phases"]
  depth: number
  path: AgentPath
}

/**
 * Builds a transcript as events arrive.
 *
 * The one-shot [`buildTranscript`] re-reads the whole log, which is right for a
 * persisted session and quadratic for a live one: a fold per event over a log
 * that grows per event. This holds the accumulation instead, so a new event
 * costs the work that event implies, and closed turns — which can never change
 * — are assembled once and kept.
 *
 * The two agree exactly; the test suite asserts it against every fixture.
 */
export class TranscriptBuilder {
  private readonly events: AgentEvent[] = []
  private readonly mainEvents: AgentEvent[] = []
  private readonly resultByCallId = new Map<string, ToolResult>()
  private readonly open = new Set<string>()
  /** Which thread each open call belongs to, so a prompt only abandons its own. */
  private readonly pathOfCall = new Map<string, AgentPath>()
  private readonly abandoned = new Set<string>()
  private readonly asks = new Map<string, AgentEvent>()
  private readonly runs = new Map<string, MutableRun>()
  private readonly sessions: SessionInfo[] = []
  private plan: readonly PlanStep[] = []
  private usage: Usage | null = null

  /** Turns that have closed. A closed turn is final, so it is assembled once. */
  private readonly closedTurns: Turn[] = []
  private prompt: AgentEvent | null = null
  /**
   * The open turn's work, already grouped.
   *
   * Grouping incrementally rather than at snapshot time is what keeps a
   * snapshot proportional to what arrived: re-running `groupTools` over the
   * whole open turn on every frame is quadratic *within* a turn, and an
   * autonomous turn with hundreds of tool calls is the normal case.
   */
  private openItems: WorkItem[] = []
  /** The trailing run of same-tool calls, not yet decided to be a group. */
  private openRun: AgentEvent[] = []
  private openToolCalls = 0
  private lastText: string | null = null
  private highestSeq = -1
  private lowestSeq = Number.POSITIVE_INFINITY
  /** Bumped on every absorbed event, so a consumer can memoize on a value that actually changes. */
  private revision = 0

  /** Feeds newly mapped events in arrival order. */
  push(incoming: readonly AgentEvent[]): void {
    for (const event of incoming) {
      // A re-delivered event is the ordinary shape of a reconnect: any
      // at-least-once transport replays its last chunk. Since `seq` is dense
      // per session, anything inside the range already absorbed is a replay and
      // is skipped — idempotent, so a resumed tail costs nothing.
      if (event.seq <= this.highestSeq && event.seq >= this.lowestSeq) continue

      // Arriving *before* everything seen is different: it would land in
      // whichever turn happens to be open, silently misfiling it. That is worth
      // refusing, and a caller holding a shuffled log has `buildTranscript`.
      if (event.seq <= this.highestSeq) {
        throw new Error(
          `TranscriptBuilder received seq ${event.seq} after ${this.highestSeq}; feed events in order or use buildTranscript`,
        )
      }

      this.highestSeq = event.seq
      if (event.seq < this.lowestSeq) this.lowestSeq = event.seq
      this.revision += 1
      this.events.push(event)
      this.absorb(event)
    }
  }

  private absorb(event: AgentEvent): void {
    const payload = event.payload

    switch (payload.type) {
      case "tool_call_started":
        this.open.add(payload.callId)
        this.pathOfCall.set(payload.callId, event.agentPath)
        break
      case "tool_call_completed":
        this.open.delete(payload.callId)
        // A result un-abandons its call. A prompt typed while the call was in
        // flight marks it abandoned; if the result then arrives, the row is
        // both "will never finish" and holding an answer, and whichever the
        // view checks first wins.
        this.abandoned.delete(payload.callId)
        this.resultByCallId.set(payload.callId, payload.result)
        break
      case "user_message":
        // A new prompt closes the book on the thread it was typed into — and
        // only that thread. A main-thread prompt says nothing about what a
        // subagent is in the middle of.
        if (!payload.synthetic) this.abandonOpenCalls(event.agentPath)
        break
      case "plan_updated":
        // A delegated run keeps its own plan. Without the guard a subagent's
        // checklist silently replaces the main agent's.
        if (event.agentPath.length === 0) this.plan = payload.steps
        else this.runFor(event.agentPath[event.agentPath.length - 1]!, event.agentPath, event.agentPath.length).plan = payload.steps
        break
      case "session_started":
        this.sessions.push(payload.session)
        break
      case "turn_completed":
        // A delegated run's own result must not overwrite the session's totals.
        if (payload.usage !== null && event.agentPath.length === 0) this.usage = payload.usage
        break
      case "permission_requested":
        this.asks.set(payload.requestId, event)
        break
      case "permission_decided":
        this.asks.delete(payload.requestId)
        break
      default:
        break
    }

    this.absorbRun(event)
    if (event.agentPath.length === 0) this.absorbMain(event)
  }

  /** Marks every call still open on one thread as abandoned, leaving other threads alone. */
  private abandonOpenCalls(path: AgentPath): void {
    const scope = pathKey(path)
    for (const callId of this.open) {
      if (pathKey(this.pathOfCall.get(callId) ?? []) !== scope) continue
      this.abandoned.add(callId)
      this.open.delete(callId)
    }
  }

  private runFor(callId: string, path: AgentPath, depth: number): MutableRun {
    let run = this.runs.get(callId)
    if (run === undefined) {
      run = {
        callId,
        taskId: null,
        kind: "other",
        label: null,
        description: null,
        transcriptId: null,
        status: null,
        lastTool: null,
        done: false,
        usage: null,
        events: [],
        plan: [],
        phases: [],
        depth,
        path,
      }
      this.runs.set(callId, run)
    }
    return run
  }

  private absorbRun(event: AgentEvent): void {
    const payload = event.payload
    const below = event.agentPath.length + 1

    // A nested run's lifecycle is also work its *parent* did, and a
    // `task_started` renders a row — so at depth it must reach the parent's
    // body, not only open a child run.
    if (
      event.agentPath.length > 0 &&
      (payload.type === "task_started" || payload.type === "task_progress" || payload.type === "task_completed")
    ) {
      const parent = event.agentPath[event.agentPath.length - 1]!
      this.runFor(parent, event.agentPath, event.agentPath.length).events.push(event)
    }

    if (payload.type === "task_started") {
      const run = this.runFor(payload.callId, [...event.agentPath, payload.callId], below)
      run.taskId = payload.taskId
      run.kind = payload.taskKind
      run.label = payload.label
      run.description = payload.description
      run.transcriptId = payload.transcriptId
      return
    }
    if (payload.type === "task_progress") {
      const run = this.runFor(payload.callId, [...event.agentPath, payload.callId], below)
      run.taskId = payload.taskId
      run.status = payload.description
      run.lastTool = payload.lastTool
      if (payload.usage !== null) run.usage = payload.usage
      return
    }
    if (payload.type === "workflow_progress") {
      const run = this.runFor(payload.callId, [...event.agentPath, payload.callId], below)
      run.taskId = payload.taskId
      run.phases = payload.phases
      return
    }
    if (payload.type === "task_completed" && payload.callId !== null) {
      const run = this.runFor(payload.callId, [...event.agentPath, payload.callId], below)
      run.taskId = payload.taskId
      run.done = true
      if (payload.usage !== null) run.usage = payload.usage
      return
    }
    if (event.agentPath.length > 0) {
      const callId = event.agentPath[event.agentPath.length - 1]!
      this.runFor(callId, event.agentPath, event.agentPath.length).events.push(event)
    }
  }

  private absorbMain(event: AgentEvent): void {
    this.mainEvents.push(event)
    const payload = event.payload

    if (payload.type === "user_message" && !payload.synthetic) {
      if (this.prompt !== null || this.openItems.length > 0 || this.openRun.length > 0) this.closeTurn(null)
      this.prompt = event
      return
    }
    if (payload.type === "turn_completed") {
      this.closeTurn(event)
      return
    }
    if (payload.type === "assistant_text") this.lastText = payload.text
    this.addWork(event)
  }

  /** Extends the open turn, keeping the trailing same-tool run open until something breaks it. */
  private addWork(event: AgentEvent): void {
    if (event.payload.type === "tool_call_started") {
      this.openToolCalls += 1
      const openName = this.openRun[0]?.payload.type === "tool_call_started" ? this.openRun[0].payload.name : null
      if (openName !== null && openName !== event.payload.name) this.flushRun()
      this.openRun.push(event)
      return
    }
    // Only a row the reader can see breaks a run; an invisible event between
    // two identical calls would otherwise split the group for no visible cause.
    if (rendersRow(event)) this.flushRun()
    this.openItems.push(event)
  }

  private flushRun(): void {
    if (this.openRun.length === 0) return
    this.openItems.push(...collapseRun(this.openRun))
    this.openRun = []
  }

  /** The open turn's items without disturbing the builder's state, for a snapshot. */
  private openWorkItems(): readonly WorkItem[] {
    return this.openRun.length === 0 ? this.openItems : [...this.openItems, ...collapseRun(this.openRun)]
  }

  private closeTurn(completed: AgentEvent | null): void {
    this.flushRun()
    this.closedTurns.push(
      assembleTurn(this.prompt, this.openItems, this.openToolCalls, completed, this.lastText, this.closedTurns.length),
    )
    this.prompt = null
    this.openItems = []
    this.openRun = []
    this.openToolCalls = 0
    this.lastText = null
  }

  /**
   * The transcript as it stands.
   *
   * Only the open turn is assembled here, so a snapshot costs the work in
   * flight rather than the session's whole history. `live` and `liveTaskIds`
   * are read at snapshot time because both describe *now* — whether a process
   * is still running is not a property of any event.
   */
  snapshot(options: { readonly live?: boolean; readonly liveTaskIds?: ReadonlySet<string> } = {}): Transcript {
    const live = options.live ?? false
    const liveTaskIds = options.liveTaskIds ?? EMPTY_TASKS

    const abandoned = new Set(this.abandoned)
    if (!live) for (const callId of this.open) abandoned.add(callId)

    const runByCallId = new Map<string, DelegatedRun>()
    for (const run of this.runs.values()) {
      runByCallId.set(run.callId, {
        ...run,
        // Copied: a run's events array is still being appended to, and a
        // consumer holding a "snapshot" whose contents grow underneath it is
        // the bug an immutable-looking type invites.
        events: [...run.events],
        done: run.done || (!live && !liveTaskIds.has(run.taskId ?? "")),
      })
    }

    const turns = [...this.closedTurns]
    const openItems = this.openWorkItems()
    if (this.prompt !== null || openItems.length > 0) {
      turns.push(assembleTurn(this.prompt, openItems, this.openToolCalls, null, this.lastText, turns.length))
    }

    return {
      revision: this.revision,
      // `events` and `resultByCallId` are the builder's own growing collections
      // rather than copies: copying either per frame would be proportional to
      // the whole session, which is the cost this class exists to avoid. They
      // are append-only and never rewritten, so a consumer memoizes on
      // `revision` — the identity of these deliberately does not change.
      events: this.mainEvents,
      turns,
      runs: [...runByCallId.values()],
      runByCallId,
      resultByCallId: this.resultByCallId,
      abandonedCallIds: abandoned,
      plan: this.plan,
      session: this.sessions.length === 0 ? null : this.sessions[this.sessions.length - 1]!,
      sessions: [...this.sessions],
      pendingAsks: [...this.asks.values()],
      usage: this.usage,
    }
  }
}

/** @responsibility Describes Claude Code's `stream-json` wire shapes and decodes one line into them without interpreting it. */

import { parseJsonLine } from "../json"
import type { JsonValue } from "../json"
import type { WireProvenance } from "../events"

/**
 * The build these shapes were read from.
 *
 * Claude Code is the one of the three that stamps its own version on the
 * stream — `system/init` carries it — so a consumer can compare what it is
 * reading against this and know when the two have drifted apart.
 */
export const CLAUDE_WIRE_PROVENANCE: WireProvenance = Object.freeze({
  cli: "Claude Code",
  version: "2.1.251",
  command: "claude -p --output-format stream-json --include-partial-messages --verbose",
  capturedOn: "2026-08-29",
})

/** Re-exported so one import gives a consumer this wire's whole vocabulary. */
export type { JsonValue }

/**
 * The line kinds Claude Code emits.
 *
 * Provider-specific by design: this is Claude Code's vocabulary, and a Codex or
 * ACP wire module declares its own. Frozen object plus derived union rather
 * than a TypeScript `enum` — an `enum` is a nominal type that does not survive
 * JSON, so a value read off the wire could never *be* one without a cast, which
 * is the opposite of what naming them is for.
 */
export const ClaudeWireType = Object.freeze({
  System: "system",
  StreamEvent: "stream_event",
  Assistant: "assistant",
  User: "user",
  Result: "result",
  RateLimit: "rate_limit_event",
  ControlRequest: "control_request",
  ControlResponse: "control_response",
} as const)

export type ClaudeWireType = (typeof ClaudeWireType)[keyof typeof ClaudeWireType]

/**
 * The `system` subtypes this build models.
 *
 * Naming them does not close the set: the CLI adds subtypes between releases
 * (`thinking_tokens` arrived unannounced), so a parser matches on these and
 * lets everything else fall through to an `unknown` event rather than failing
 * the line. The union is a checklist of what is handled, not a claim about what
 * exists.
 */
export const ClaudeSystemSubtype = Object.freeze({
  Init: "init",
  Status: "status",
  TaskStarted: "task_started",
  TaskProgress: "task_progress",
  TaskUpdated: "task_updated",
  TaskNotification: "task_notification",
  TaskSummary: "task_summary",
  ThinkingTokens: "thinking_tokens",
  HookStarted: "hook_started",
  HookResponse: "hook_response",
  PostTurnSummary: "post_turn_summary",
  BackgroundTasksChanged: "background_tasks_changed",
  CompactBoundary: "compact_boundary",
  PermissionDenied: "permission_denied",
} as const)

export type ClaudeSystemSubtype = (typeof ClaudeSystemSubtype)[keyof typeof ClaudeSystemSubtype]

/** The Anthropic SSE frame types carried inside `stream_event.event`. */
export const ClaudeStreamFrameType = Object.freeze({
  MessageStart: "message_start",
  ContentBlockStart: "content_block_start",
  ContentBlockDelta: "content_block_delta",
  ContentBlockStop: "content_block_stop",
  MessageDelta: "message_delta",
  MessageStop: "message_stop",
} as const)

export type ClaudeStreamFrameType = (typeof ClaudeStreamFrameType)[keyof typeof ClaudeStreamFrameType]

/** The delta kinds an open content block streams. */
export const ClaudeContentDeltaType = Object.freeze({
  Text: "text_delta",
  Thinking: "thinking_delta",
  Signature: "signature_delta",
  InputJson: "input_json_delta",
} as const)

export type ClaudeContentDeltaType = (typeof ClaudeContentDeltaType)[keyof typeof ClaudeContentDeltaType]

/**
 * The kinds of delegated work a `task_started` announces.
 *
 * `local_bash` is a backgrounded shell rather than an agent, which is why it
 * carries no `subagent_type` and reports no usage.
 */
export const ClaudeTaskType = Object.freeze({
  Agent: "local_agent",
  Workflow: "local_workflow",
  Bash: "local_bash",
} as const)

export type ClaudeTaskType = (typeof ClaudeTaskType)[keyof typeof ClaudeTaskType]

/** The content block kinds, shared by the streamed and committed positions. */
export const ClaudeContentBlockType = Object.freeze({
  Text: "text",
  Thinking: "thinking",
  ToolUse: "tool_use",
  ToolResult: "tool_result",
  Image: "image",
} as const)

export type ClaudeContentBlockType = (typeof ClaudeContentBlockType)[keyof typeof ClaudeContentBlockType]

/**
 * Anthropic's token accounting. Present on `result`, on committed `assistant`
 * messages, and on the `message_start`/`message_delta` stream frames — but with
 * different fields filled in each place, so everything past the four counts is
 * optional.
 */
export interface WireUsage {
  readonly input_tokens?: number
  readonly output_tokens?: number
  readonly cache_read_input_tokens?: number
  readonly cache_creation_input_tokens?: number
  readonly cache_creation?: {
    readonly ephemeral_5m_input_tokens?: number
    readonly ephemeral_1h_input_tokens?: number
  }
  readonly server_tool_use?: {
    readonly web_search_requests?: number
    readonly web_fetch_requests?: number
  }
  readonly service_tier?: string
  readonly speed?: string
  /**
   * Per-request breakdown when one turn took several model calls. Sent as an
   * explicit `null` on the CLI's synthetic messages, so consumers must treat
   * "present but null" as "absent" rather than trusting the key.
   */
  readonly iterations?: readonly WireUsage[] | null
}

/** A content block, identical in the streamed and committed positions. */
export type WireContentBlock =
  | { readonly type: "text"; readonly text: string }
  | {
      readonly type: "thinking"
      readonly thinking?: string
      readonly signature?: string
    }
  | {
      readonly type: "tool_use"
      readonly id: string
      readonly name: string
      readonly input?: JsonValue
      readonly caller?: JsonValue
    }
  | { readonly type: string; readonly [key: string]: JsonValue | undefined }

/** One incremental update to an open content block. */
export type WireContentDelta =
  | { readonly type: "text_delta"; readonly text: string }
  | { readonly type: "thinking_delta"; readonly thinking: string }
  | { readonly type: "signature_delta"; readonly signature: string }
  /**
   * Fragments of a tool call's arguments. These are *not* individually
   * parseable — only the concatenation of every fragment for one block is
   * valid JSON.
   */
  | { readonly type: "input_json_delta"; readonly partial_json: string }
  | { readonly type: string }

/**
 * One Anthropic SSE frame, as carried inside `stream_event.event`. Blocks are
 * addressed by `index` within the message opened by `message_start`; a block's
 * identity arrives once, up front, in `content_block_start`.
 */
export type WireStreamFrame =
  | {
      readonly type: "message_start"
      readonly message: {
        readonly id: string
        readonly model: string
        readonly role: string
        readonly usage?: WireUsage
      }
    }
  | {
      readonly type: "content_block_start"
      readonly index: number
      readonly content_block: WireContentBlock
    }
  | {
      readonly type: "content_block_delta"
      readonly index: number
      readonly delta: WireContentDelta
    }
  | { readonly type: "content_block_stop"; readonly index: number }
  | {
      readonly type: "message_delta"
      readonly delta: { readonly stop_reason?: string | null }
      readonly usage?: WireUsage
    }
  | { readonly type: "message_stop" }
  | { readonly type: string }

/** A tool result's payload: one flat string, or a block array for structured tools. */
export type WireToolResultContent = string | readonly WireContentBlock[]

/** A `user` line's message. Human prompts arrive as a bare string; everything the CLI feeds back arrives as blocks. */
export interface WireUserMessage {
  readonly role: "user"
  readonly content: string | readonly WireContentBlock[]
}

/** A committed `assistant` message. Claude Code sends one line per content block, so `content` has length 1. */
export interface WireAssistantMessage {
  readonly id: string
  readonly model: string
  readonly role: "assistant"
  readonly content: readonly WireContentBlock[]
  readonly stop_reason?: string | null
  readonly usage?: WireUsage
}

/** Usage reported for one background task or workflow run. */
export interface WireTaskUsage {
  readonly total_tokens?: number
  readonly tool_uses?: number
  readonly duration_ms?: number
}

/** What one `system/init` advertises: the whole session, as the CLI sees it. */
export interface WireInitEvent {
  readonly type: "system"
  readonly subtype: "init"
  readonly session_id: string
  readonly cwd: string
  readonly model: string
  readonly tools: readonly string[]
  readonly slash_commands?: readonly string[]
  readonly terminal_slash_commands?: readonly string[]
  readonly skills?: readonly string[]
  readonly agents?: readonly string[]
  readonly mcp_servers?: readonly { readonly name: string; readonly status: string }[]
  readonly plugins?: readonly { readonly name: string; readonly version?: string; readonly source?: string }[]
  readonly permissionMode?: string
  readonly output_style?: string
  readonly claude_code_version?: string
}

/** A delegated run beginning: a subagent, a workflow, or a backgrounded shell. */
export interface WireTaskStartedEvent {
  readonly type: "system"
  readonly subtype: "task_started"
  readonly task_id: string
  readonly tool_use_id: string
  readonly task_type: string
  readonly description?: string
  readonly subagent_type?: string
  readonly workflow_name?: string
  readonly prompt?: string
}

/**
 * A delegated run's live status.
 *
 * `workflow_progress` rides only some of these, and is the only window into a
 * workflow's agents — they write nothing else to the stream.
 */
export interface WireTaskProgressEvent {
  readonly type: "system"
  readonly subtype: "task_progress"
  readonly task_id: string
  readonly tool_use_id: string
  readonly description?: string
  readonly last_tool_name?: string
  readonly usage?: { readonly total_tokens?: number; readonly tool_uses?: number; readonly duration_ms?: number }
  readonly workflow_progress?: readonly JsonValue[]
}

/** A delegated run finishing, with where its output was written. */
export interface WireTaskNotificationEvent {
  readonly type: "system"
  readonly subtype: "task_notification"
  readonly task_id: string
  readonly tool_use_id?: string
  readonly status?: string
  readonly summary?: string
  readonly output_file?: string
}

/** The seam a compaction left, and what it cost. */
export interface WireCompactBoundaryEvent {
  readonly type: "system"
  readonly subtype: "compact_boundary"
  readonly compact_metadata?: {
    readonly trigger?: string
    readonly pre_tokens?: number
    readonly post_tokens?: number
  }
}

/** A call refused without ever being asked about. */
export interface WirePermissionDeniedEvent {
  readonly type: "system"
  readonly subtype: "permission_denied"
  readonly tool_name: string
  readonly tool_use_id: string
  readonly message?: string
}

/** A hook running. `hook_response` adds the outcome. */
export interface WireHookEvent {
  readonly type: "system"
  readonly subtype: "hook_started" | "hook_response"
  readonly hook_name?: string
  readonly hook_event?: string
  readonly outcome?: string
  readonly exit_code?: number
}

/** A system line this build does not model. Open on purpose: the CLI adds subtypes. */
export interface WireUnknownSystemEvent {
  readonly type: "system"
  readonly subtype: string
  readonly [key: string]: JsonValue | undefined
}

/** Everything the `system` channel can carry. */
export type WireSystemEvent =
  | WireInitEvent
  | WireTaskStartedEvent
  | WireTaskProgressEvent
  | WireTaskNotificationEvent
  | WireCompactBoundaryEvent
  | WirePermissionDeniedEvent
  | WireHookEvent
  | WireUnknownSystemEvent

/** Any decoded line, before anything past `type` has been checked. */
export interface WireLine {
  readonly type: string
  readonly [key: string]: JsonValue | undefined
}

/**
 * One decoded line. Every arm keeps the fields this library reads and tolerates
 * the rest: the CLI adds keys and whole subtypes between releases, and a parser
 * that fails a line over an unknown field loses content it could have shown.
 *
 * These shapes describe the wire; they do not police it. A declared type is a
 * claim about bytes, not a check on them, so the mapper reads every field
 * through the shared readers rather than trusting the declaration.
 */
export type WireEvent =
  | WireSystemEvent
  | {
      readonly type: "stream_event"
      readonly event: WireStreamFrame
      readonly session_id: string
      readonly uuid: string
      readonly parent_tool_use_id?: string | null
    }
  | {
      readonly type: "assistant"
      readonly message: WireAssistantMessage
      readonly session_id: string
      readonly uuid: string
      readonly parent_tool_use_id?: string | null
      readonly subagent_type?: string | null
      readonly task_description?: string | null
    }
  | {
      readonly type: "user"
      readonly message: WireUserMessage
      readonly session_id: string
      readonly uuid: string
      readonly timestamp?: string
      readonly parent_tool_use_id?: string | null
      readonly tool_use_result?: JsonValue
      readonly subagent_type?: string | null
      readonly task_description?: string | null
      readonly isReplay?: boolean
      readonly isSynthetic?: boolean
    }
  | {
      readonly type: "result"
      readonly subtype: string
      readonly session_id: string
      readonly uuid?: string
      readonly [key: string]: JsonValue | undefined
    }
  | {
      readonly type: "rate_limit_event"
      readonly rate_limit_info: {
        readonly status?: string
        readonly resetsAt?: number
        readonly rateLimitType?: string
        readonly overageStatus?: string
        readonly overageDisabledReason?: string
        readonly isUsingOverage?: boolean
      }
      readonly session_id: string
      readonly uuid: string
    }
  | {
      readonly type: "control_request"
      readonly request_id: string
      readonly request: { readonly subtype: string; readonly [key: string]: JsonValue | undefined }
    }
  | { readonly type: "control_response"; readonly response: JsonValue }
  | { readonly type: string; readonly [key: string]: JsonValue | undefined }

/** What a line that could not be decoded at all becomes. */
export interface WireParseFailure {
  readonly ok: false
  readonly line: string
  readonly reason: string
}

export interface WireParseSuccess {
  readonly ok: true
  /**
   * What the parser actually verified: an object with a string `type`.
   *
   * Not one of the arms above. Returning the union would claim fields nothing
   * checked; the arms describe the wire, and a consumer narrows to one after
   * checking, the way this package's own mapper does.
   */
  readonly line: WireLine
}

export type WireParseResult = WireParseSuccess | WireParseFailure

/**
 * Decodes one line of `--output-format stream-json`.
 *
 * Failure is returned rather than thrown: a stream is read for as long as the
 * process runs, and one malformed line — a truncated write, a stray log — must
 * not end the transcript. Blank lines are a failure with an explicit reason so
 * a caller can filter them knowingly instead of by accident.
 */
/**
 * Decodes one line of Claude Code's stream.
 *
 * The decoding itself is shared — every provider's wire is newline-delimited
 * JSON, and one copy per provider is one place per provider for a bug in it to
 * live. What stays here is the naming and the return type.
 */
export function parseWireLine(line: string): WireParseResult {
  const result = parseJsonLine(line)
  return result.ok ? { ok: true, line: result.line as WireLine } : result
}

/** Decodes a whole capture, keeping failures in place. */
export function parseWireLines(text: string): readonly WireParseResult[] {
  return text
    .split("\n")
    .filter((line) => line.trim().length > 0)
    .map(parseWireLine)
}

/** @responsibility States, as data, which Claude Code line kind becomes which normalized event. */

import { asRecord, asString } from "../json"
import { AgentEventType, PlanStepStatus, TaskKind } from "../events"
import {
  ClaudeTaskType,
  ClaudeContentBlockType,
  ClaudeContentDeltaType,
  ClaudeStreamFrameType,
  ClaudeSystemSubtype,
  ClaudeWireType,
} from "./wire"
import type { JsonValue, WireEvent } from "./wire"

/**
 * A line's kind, at the granularity the mapping actually turns on.
 *
 * Not just `type`: a `stream_event` means nothing without its frame, a
 * `content_block_delta` nothing without its delta kind, and an `assistant`
 * line's outcome depends on the block it carries. The key is the smallest
 * thing that determines the answer.
 */
export type ClaudeWireKind = string

/** What one kind of line produces. */
export interface ClaudeMappingEntry {
  /**
   * The normalized events this kind can produce.
   *
   * A set rather than one value because a single line legitimately produces
   * several — a `tool_use` block is a call *and*, when it is a plan tool, a
   * plan update. Empty means the line deliberately produces nothing.
   */
  readonly emits: readonly AgentEventType[]
  /** Why, in one line. For an empty `emits` this is the whole justification. */
  readonly note: string
}

/**
 * The provider-to-contract mapping, as data.
 *
 * Written down rather than left implicit in the mapper's switches so the
 * translation can be *read* — and tested. A second harness fills in a table of
 * the same shape against the same [`AgentEventType`] values, which is what
 * makes "swap the mapper, keep the components" a checkable claim rather than an
 * aspiration.
 *
 * The test suite walks every fixture line, computes its kind, and asserts the
 * mapper emitted exactly what this table promises. A kind missing from here is
 * a line nobody decided about.
 */
export const CLAUDE_EVENT_MAPPING: Readonly<Record<ClaudeWireKind, ClaudeMappingEntry>> = Object.freeze({
  // ---------- session and turn ----------
  [`${ClaudeWireType.System}/${ClaudeSystemSubtype.Init}`]: {
    emits: [AgentEventType.SessionStarted, AgentEventType.ModelChanged],
    note: "one per turn, not per session; a model change is derived from two of them",
  },
  [ClaudeWireType.Result]: {
    emits: [AgentEventType.TurnCompleted],
    note: "the turn terminator, carrying usage, cost and stop reason",
  },

  // ---------- conversation ----------
  [`${ClaudeWireType.Assistant}/${ClaudeContentBlockType.Text}`]: {
    emits: [AgentEventType.AssistantText],
    note: "committed prose; supersedes whatever the deltas previewed",
  },
  [`${ClaudeWireType.Assistant}/${ClaudeContentBlockType.Thinking}`]: {
    emits: [AgentEventType.Reasoning],
    note: "committed reasoning",
  },
  [`${ClaudeWireType.Assistant}/${ClaudeContentBlockType.ToolUse}`]: {
    emits: [AgentEventType.ToolCallStarted, AgentEventType.PlanUpdated],
    note: "a call, plus a plan update when the call is TodoWrite or TaskCreate/TaskUpdate",
  },
  [`${ClaudeWireType.User}/text`]: {
    emits: [AgentEventType.UserMessage, AgentEventType.Error],
    note: "what the user typed, unless it is the CLI's interruption notice",
  },
  [`${ClaudeWireType.User}/${ClaudeContentBlockType.ToolResult}`]: {
    emits: [AgentEventType.ToolCallCompleted, AgentEventType.PlanUpdated],
    note: "a result, plus a plan update when it settles a TaskCreate's id",
  },

  // ---------- streamed preview ----------
  [`${ClaudeWireType.StreamEvent}/${ClaudeStreamFrameType.MessageStart}`]: {
    emits: [],
    note: "records the message id, which is the join key for every block frame after it",
  },
  [`${ClaudeWireType.StreamEvent}/${ClaudeStreamFrameType.ContentBlockStart}`]: {
    emits: [AgentEventType.Delta],
    note: "opens a block and names a tool call before its arguments stream",
  },
  [`${ClaudeWireType.StreamEvent}/${ClaudeStreamFrameType.ContentBlockDelta}/${ClaudeContentDeltaType.Text}`]: {
    emits: [AgentEventType.Delta],
    note: "prose fragment",
  },
  [`${ClaudeWireType.StreamEvent}/${ClaudeStreamFrameType.ContentBlockDelta}/${ClaudeContentDeltaType.Thinking}`]: {
    emits: [AgentEventType.Delta],
    note: "reasoning fragment; the block's start already said which kind it is",
  },
  [`${ClaudeWireType.StreamEvent}/${ClaudeStreamFrameType.ContentBlockDelta}/${ClaudeContentDeltaType.InputJson}`]: {
    emits: [AgentEventType.Delta],
    note: "tool-argument fragment, parseable only once every fragment is concatenated",
  },
  [`${ClaudeWireType.StreamEvent}/${ClaudeStreamFrameType.ContentBlockDelta}/${ClaudeContentDeltaType.Signature}`]: {
    emits: [],
    note: "signs a thinking block; not display content",
  },
  [`${ClaudeWireType.StreamEvent}/${ClaudeStreamFrameType.ContentBlockStop}`]: {
    emits: [AgentEventType.Delta],
    note: "closes a block",
  },
  [`${ClaudeWireType.StreamEvent}/${ClaudeStreamFrameType.MessageDelta}`]: {
    emits: [],
    note: "terminal metadata the result line already carries",
  },
  [`${ClaudeWireType.StreamEvent}/${ClaudeStreamFrameType.MessageStop}`]: {
    emits: [],
    note: "terminal metadata the result line already carries",
  },

  // ---------- delegated work ----------
  [`${ClaudeWireType.System}/${ClaudeSystemSubtype.TaskStarted}`]: {
    emits: [AgentEventType.TaskStarted],
    note: "a subagent, a workflow or a backgrounded shell begins",
  },
  [`${ClaudeWireType.System}/${ClaudeSystemSubtype.TaskProgress}`]: {
    emits: [AgentEventType.TaskProgress, AgentEventType.WorkflowProgress],
    note: "a live status line, plus a workflow's phase-and-agent board when it carries one",
  },
  [`${ClaudeWireType.System}/${ClaudeSystemSubtype.TaskUpdated}`]: {
    emits: [AgentEventType.TaskCompleted],
    note: "a status patch; the only completion signal a task that never notifies sends",
  },
  [`${ClaudeWireType.System}/${ClaudeSystemSubtype.TaskNotification}`]: {
    emits: [AgentEventType.TaskCompleted],
    note: "the run's outcome and where its output was written",
  },
  [`${ClaudeWireType.System}/${ClaudeSystemSubtype.TaskSummary}`]: {
    emits: [AgentEventType.Activity],
    note: "a one-line gloss; nothing to show when it carries no detail",
  },
  [`${ClaudeWireType.System}/${ClaudeSystemSubtype.BackgroundTasksChanged}`]: {
    emits: [AgentEventType.BackgroundTasksChanged],
    note: "the whole outstanding set, republished; half of whether a session is idle",
  },

  // ---------- session-level reports ----------
  [`${ClaudeWireType.System}/${ClaudeSystemSubtype.Status}`]: {
    emits: [AgentEventType.StatusChanged],
    note: "requesting, compacting, and the permission mode",
  },
  [`${ClaudeWireType.System}/${ClaudeSystemSubtype.ThinkingTokens}`]: {
    emits: [AgentEventType.ThinkingProgress],
    note: "a running estimate of the open thinking block",
  },
  [`${ClaudeWireType.System}/${ClaudeSystemSubtype.HookStarted}`]: {
    emits: [AgentEventType.Hook],
    note: "a hook began",
  },
  [`${ClaudeWireType.System}/${ClaudeSystemSubtype.HookResponse}`]: {
    emits: [AgentEventType.Hook],
    note: "a hook finished, with its outcome and exit code",
  },
  [`${ClaudeWireType.System}/${ClaudeSystemSubtype.PostTurnSummary}`]: {
    emits: [AgentEventType.PostTurnSummary],
    note: "a one-line recap emitted just before the turn's result",
  },
  [`${ClaudeWireType.System}/${ClaudeSystemSubtype.CompactBoundary}`]: {
    emits: [AgentEventType.ContextCompacted],
    note: "the seam where a compaction dropped the earlier conversation",
  },
  [`${ClaudeWireType.System}/${ClaudeSystemSubtype.PermissionDenied}`]: {
    emits: [AgentEventType.PermissionDenied],
    note: "a call refused without being asked about",
  },
  [ClaudeWireType.RateLimit]: {
    emits: [AgentEventType.RateLimited],
    note: "only when a limit is reached or overage is in use; the steady state emits nothing",
  },

  // ---------- asks ----------
  [`${ClaudeWireType.ControlRequest}/can_use_tool`]: {
    emits: [AgentEventType.PermissionRequested],
    note: "the one duplex exchange: the harness blocks until it is answered, and the reply is written back on stdin",
  },
  [ClaudeWireType.ControlResponse]: {
    emits: [AgentEventType.PermissionDecided],
    note: "retires a pending ask and records which way it went; neither direction carries a timestamp",
  },
})

/**
 * Claude's task vocabulary, mapped to ours.
 *
 * A lookup rather than a chain of comparisons: the mapping *is* data, and
 * written as data it can be read at a glance, exhaustively checked by the
 * compiler against the provider's own union, and extended without touching
 * control flow. `Other` is the fallback for a kind a later release invents.
 */
export const CLAUDE_TASK_KIND: Readonly<Record<ClaudeTaskType, TaskKind>> = Object.freeze({
  [ClaudeTaskType.Agent]: TaskKind.Agent,
  [ClaudeTaskType.Workflow]: TaskKind.Workflow,
  [ClaudeTaskType.Bash]: TaskKind.Bash,
})

/** Claude's plan-step words, mapped to ours. Anything unrecognized is still pending. */
export const CLAUDE_PLAN_STATUS: Readonly<Record<string, PlanStepStatus>> = Object.freeze({
  pending: PlanStepStatus.Pending,
  in_progress: PlanStepStatus.InProgress,
  completed: PlanStepStatus.Completed,
})

/** Reads a `task_type` off the wire as one of ours. */
export function claudeTaskKind(taskType: string | null): TaskKind {
  if (taskType === null) return TaskKind.Other
  return CLAUDE_TASK_KIND[taskType as ClaudeTaskType] ?? TaskKind.Other
}

/** Reads a plan step's status off the wire as one of ours. */
export function claudePlanStatus(status: string | null): PlanStepStatus {
  if (status === null) return PlanStepStatus.Pending
  return CLAUDE_PLAN_STATUS[status] ?? PlanStepStatus.Pending
}

/**
 * The mapping key for one decoded line.
 *
 * Mirrors the granularity the table is written at, so a caller can look up what
 * a line is supposed to produce — which is what the test suite does, and what a
 * host would do to explain an event to a reader.
 */
export function claudeWireKind(event: WireEvent): ClaudeWireKind {
  const line = asRecord(event as unknown as JsonValue)
  const type = asString(line.type) ?? "unknown"

  if (type === ClaudeWireType.StreamEvent) {
    const frame = asRecord(line.event)
    const frameType = asString(frame.type) ?? "unknown"
    if (frameType !== ClaudeStreamFrameType.ContentBlockDelta) return `${type}/${frameType}`
    return `${type}/${frameType}/${asString(asRecord(frame.delta).type) ?? "unknown"}`
  }

  if (type === ClaudeWireType.Assistant || type === ClaudeWireType.User) {
    // A `user` line's content is one of two unrelated shapes and nothing labels
    // which — a bare string is what the human typed, an array is what the CLI
    // fed back — so the shape itself is the discriminator.
    const content = asRecord(line.message).content
    const text = asString(content)
    if (text !== null) return `${type}/text`
    const blocks = Array.isArray(content) ? content : []
    if (blocks.length === 0) return `${type}/empty`
    return `${type}/${asString(asRecord(blocks[0]).type) ?? "unknown"}`
  }

  if (type === ClaudeWireType.System) {
    return `${type}/${asString(line.subtype) ?? "unknown"}`
  }

  if (type === ClaudeWireType.ControlRequest) {
    return `${type}/${asString(asRecord(line.request).subtype) ?? "unknown"}`
  }

  return type
}

/** What a line kind is declared to produce, or null for a kind nobody has decided about. */
export function claudeMappingFor(kind: ClaudeWireKind): ClaudeMappingEntry | null {
  return CLAUDE_EVENT_MAPPING[kind] ?? null
}

/** @responsibility Turns Claude Code `stream-json` lines into normalized agent events, holding the little state that requires. */

import { pathKey } from "../events"
import type {
  AgentEvent,
  AgentEventPayload,
  AgentPath,
  BlockRef,
  PlanStep,
  SessionInfo,
  AgentStreamMapper,
  MapperOptions,
  ToolResult,
  Usage,
  WorkflowAgentProgress,
  WorkflowPhaseProgress,
} from "../events"
import { claudePlanStatus, claudeTaskKind } from "./mapping"
import { asArray, asNumber, asObject, asOneOf, asRecord, asString, asStrings } from "../json"
import { toolKind, toolTitle } from "./tools"
import type {
  JsonValue,
  WireLine,
  WireContentBlock,
  WireEvent,
  WireStreamFrame,
  WireUsage,
} from "./wire"
import {
  ClaudeContentBlockType,
  ClaudeContentDeltaType,
  ClaudeStreamFrameType,
  ClaudeSystemSubtype,
  ClaudeWireType,
  parseWireLine,
} from "./wire"

/** Claude Code wraps a failed tool's message in this framing. It is wire syntax, not content — `isError` already carries the fact. */
const ERROR_OPEN = "<tool_use_error>"
const ERROR_CLOSE = "</tool_use_error>"

/**
 * How the CLI narrates an interruption inside an ordinary `user` line.
 *
 * Prose matching, which is safe here only because the truth arrives separately
 * on `result.terminal_reason`: a reworded notice costs one stray transcript row,
 * never a missed turn end.
 */
const INTERRUPT_PREFIX = "[Request interrupted by user"

/**
 * How many recent line uuids are remembered for replay detection.
 *
 * A replay is always adjacent — a reconnect re-sends its last chunk — so a
 * bounded window catches it without growing with the session.
 */
const UUID_MEMORY = 2048

function stripToolUseError(text: string): string {
  const trimmed = text.trim()
  if (!trimmed.startsWith(ERROR_OPEN) || !trimmed.endsWith(ERROR_CLOSE)) return text
  return trimmed.slice(ERROR_OPEN.length, trimmed.length - ERROR_CLOSE.length).trim()
}

function normalizeUsage(usage: JsonValue | undefined, costUsd: number | null): Usage | null {
  // Absent usage is absent, not zero: `asRecord` would flatten a missing block
  // to `{}` and every counter to a confident zero, which is a claim the line
  // never made. `asObject` keeps the two answers apart.
  const fields = asObject(usage)
  if (fields === null) return null
  const input = asNumber(fields.input_tokens)
  const output = asNumber(fields.output_tokens)
  const cacheRead = asNumber(fields.cache_read_input_tokens)
  const cacheCreation = asNumber(fields.cache_creation_input_tokens)
  const counters = [input, output, cacheRead, cacheCreation].filter((count): count is number => count !== null)
  return {
    // Summed rather than sent: Anthropic reports the parts, so the total is
    // derived — but only from the parts that were actually reported, and only
    // from the ones that were really numbers.
    totalTokens: counters.length === 0 ? null : counters.reduce((sum, count) => sum + count, 0),
    inputTokens: input,
    outputTokens: output,
    cacheReadTokens: cacheRead,
    cacheCreationTokens: cacheCreation,
    // Claude folds reasoning into its output count and reports no separate
    // figure, so this is unreported rather than zero.
    reasoningTokens: null,
    ...(costUsd === null ? {} : { totalCostUsd: costUsd }),
  }
}

/** Flattens either tool-result shape to text, and collects any images as `data:` URLs. */
function readToolResult(block: Record<string, JsonValue>, sidecar: JsonValue | undefined): ToolResult {
  const content = block.content
  const images: string[] = []
  let text = ""

  const flat = asString(content)
  if (flat !== null) {
    text = flat
  } else if (Array.isArray(content)) {
    const parts: string[] = []
    for (const entry of content) {
      const item = asRecord(entry)
      const itemText = asString(item.text)
      if (item.type === ClaudeContentBlockType.Text && itemText !== null) parts.push(itemText)
      if (item.type === ClaudeContentBlockType.Image) {
        const source = asRecord(item.source)
        const data = asString(source.data)
        if (data !== null && data.length > 0) {
          images.push(`data:${asString(source.media_type) ?? "image/png"};base64,${data}`)
        }
      }
    }
    text = parts.join("\n")
  }

  return {
    text: stripToolUseError(text),
    isError: block.is_error === true,
    structured: sidecar ?? null,
    images,
  }
}

/** Pulls the step id out of `TaskCreate`'s result text, which is the only place it appears. */
const CREATED_ID = /Task #(\d+)/

/** Reads `TodoWrite`'s argument into plan steps, tolerating a shape that has moved before. */
function readPlan(input: JsonValue): readonly PlanStep[] | null {
  const todos = asRecord(input).todos
  if (!Array.isArray(todos)) return null
  const steps: PlanStep[] = []
  for (const entry of todos) {
    const todo = asRecord(entry)
    const content = asString(todo.content)
    if (content === null) continue
    steps.push({
      id: null,
      content,
      status: claudePlanStatus(asString(todo.status)),
      ...(asString(todo.activeForm) !== null ? { activeForm: asString(todo.activeForm)! } : {}),
    })
  }
  return steps
}

/**
 * Maps one session's stdout into normalized events.
 *
 * Stateful by necessity, and the state is small and named: which message is
 * open (stream frames address blocks by index within it), how many blocks each
 * message has committed (Claude Code sends no index on committed lines), which
 * call spawned which agent (so nesting is a path rather than a flat id), and
 * what the last `init` said (so a model change is detectable at all).
 *
 * One instance per session. Feeding two sessions through one mapper interleaves
 * their block indices and produces silently wrong joins.
 */
export class ClaudeStreamMapper implements AgentStreamMapper {
  private seq: number
  /**
   * The open message per thread.
   *
   * Keyed by agent path, not global: a subagent's frames interleave with the
   * main thread's on one stdout, and a single slot means the last
   * `message_start` wins — so main-thread deltas would join a subagent's
   * message and the preview would never reconcile with its committed block.
   */
  private readonly openMessage = new Map<string, string>()
  /** Committed block count per thread and message id — the source of the derived index. */
  private readonly committedBlocks = new Map<string, number>()
  /**
   * Line uuids already absorbed, newest last.
   *
   * A replayed committed line would otherwise be counted a second time and
   * shift every later block index in that message by one, breaking the
   * delta join silently. Bounded, because a session's uuids are unbounded and
   * a replay is always near.
   */
  private readonly seenUuids = new Set<string>()
  /** The agent path a tool call's own events belong to, keyed by call id. */
  private readonly pathByCall = new Map<string, AgentPath>()
  /**
   * The plan as built so far.
   *
   * Held here rather than derived downstream because the incremental plan tools
   * put a step's id in the tool *result*, so the fold would have to correlate a
   * call, its arguments and its result to draw a checklist — which is exactly
   * the work this layer exists to do once.
   */
  private planSteps: PlanStep[] = []
  /** `TaskCreate` calls whose id has not come back yet, keyed by call id. */
  private readonly pendingPlanSteps = new Map<string, PlanStep>()
  private lastSession: SessionInfo | null = null
  /** How many `init` lines have been seen, which is what `SessionInfo.initIndex` reports. */
  private initCount = 0

  constructor(options: MapperOptions = {}) {
    this.seq = options.startSeq ?? 0
  }

  /** Decodes and maps one line. An undecodable line becomes a single `error` event rather than nothing. */
  push(line: string): readonly AgentEvent[] {
    const parsed = parseWireLine(line)
    if (!parsed.ok) {
      return [
        // The path is genuinely unrecoverable from an unparsed line, but the
        // session is not: it is whichever session this mapper is reading.
        this.build(
          { type: "error", message: `unreadable line: ${parsed.reason}` },
          this.lastSession?.sessionId ?? "unknown",
          [],
          null,
          { line: parsed.line },
        ),
      ]
    }
    return this.map(parsed.line)
  }

  /** Maps an already-decoded line. */
  map(event: WireLine): readonly AgentEvent[] {
    const raw = event as JsonValue
    const line = asRecord(raw)
    // A line delivered twice — a replayed tail, two captures concatenated —
    // must be absorbed once: counting a committed block a second time shifts
    // every later index in that message and breaks the delta join silently.
    const uuid = asString(asRecord(raw).uuid)
    if (uuid !== null) {
      if (this.seenUuids.has(uuid)) return []
      this.seenUuids.add(uuid)
      if (this.seenUuids.size > UUID_MEMORY) {
        const oldest = this.seenUuids.values().next()
        if (!oldest.done) this.seenUuids.delete(oldest.value)
      }
    }
    const sessionId = asString(line.session_id) ?? this.lastSession?.sessionId ?? "unknown"
    const path = this.pathOf(line.parent_tool_use_id)
    const ts = asString(line.timestamp)

    switch (event.type) {
      case ClaudeWireType.System:
        return this.mapSystem(asString(asRecord(raw).subtype) ?? "unknown", sessionId, path, ts, raw)
      case ClaudeWireType.StreamEvent:
        // Read, not asserted: `mapStreamFrame` narrows every field it uses.
        return this.wrap(this.mapStreamFrame(asRecord(line.event) as WireStreamFrame, path), sessionId, path, ts, raw)
      case ClaudeWireType.Assistant:
        return this.mapAssistant(asRecord(raw), sessionId, path, ts, raw)
      case ClaudeWireType.User:
        return this.mapUser(asRecord(raw), sessionId, path, ts, raw)
      case ClaudeWireType.Result:
        return this.mapResult(asRecord(raw), sessionId, path, ts, raw)
      case ClaudeWireType.RateLimit: {
        const info = asRecord(asRecord(raw).rate_limit_info)
        const status = asString(info.status) ?? "unknown"
        // The steady state is reported constantly and is not worth a row; only
        // a limit that has been reached or is being billed as overage is.
        if (status === "allowed" && info.isUsingOverage !== true) return []
        const resetsAt = asNumber(info.resetsAt)
        return this.wrap(
          {
            type: "rate_limited",
            status,
            resetsAt: resetsAt === null ? null : new Date(resetsAt * 1000).toISOString(),
            window: asString(info.rateLimitType),
            usingOverage: info.isUsingOverage === true,
          },
          sessionId,
          path,
          ts,
          raw,
        )
      }
      case ClaudeWireType.ControlRequest: {
        const request = asRecord(asRecord(raw).request)
        if (asString(request.subtype) !== "can_use_tool") {
          return this.wrap({ type: "unknown", wireType: "control_request", subtype: asString(request.subtype) }, sessionId, path, ts, raw)
        }
        return this.wrap(
          {
            type: "permission_requested",
            requestId: asString(asRecord(raw).request_id) ?? "",
            callId: asString(request.tool_use_id) ?? "",
            toolName: asString(request.tool_name) ?? "",
            input: request.input ?? null,
            // The wire names this `decision_reason_type` ("rule", "mode", ...).
            // `decision_reason` is accepted too because older builds sent it,
            // and a null reason would quietly turn a rule-driven ask into an
            // unexplained one.
            reason: asString(request.decision_reason_type) ?? asString(request.decision_reason),
            displayName: asString(request.display_name),
            description: asString(request.description),
          },
          sessionId,
          path,
          ts,
          raw,
        )
      }
      case ClaudeWireType.ControlResponse: {
        const envelope = asRecord(asRecord(raw).response)
        const answer = asRecord(envelope.response)
        return this.wrap(
          {
            type: "permission_decided",
            requestId: asString(envelope.request_id) ?? "",
            decision: asOneOf(answer.behavior, ["allow", "deny"] as const),
            message: asString(answer.message),
          },
          sessionId,
          path,
          ts,
          raw,
        )
      }
      default:
        return this.wrap({ type: "unknown", wireType: event.type, subtype: asString(asRecord(raw).subtype) }, sessionId, path, ts, raw)
    }
  }

  private mapSystem(
    subtype: string,
    sessionId: string,
    path: AgentPath,
    ts: string | null,
    raw: JsonValue,
  ): readonly AgentEvent[] {
    const line = asRecord(raw)
    switch (subtype) {
      case ClaudeSystemSubtype.Init: {
        const session: SessionInfo = {
          sessionId,
          model: asString(line.model),
          cwd: asString(line.cwd),
          tools: asStrings(line.tools),
          slashCommands: asStrings(line.slash_commands),
          agents: asStrings(line.agents),
          skills: asStrings(line.skills),
          mcpServers: Array.isArray(line.mcp_servers)
            ? line.mcp_servers.map((entry) => ({
                name: asString(asRecord(entry).name) ?? "",
                status: asString(asRecord(entry).status) ?? "unknown",
              }))
            : [],
          terminalSlashCommands: asStrings(line.terminal_slash_commands),
          plugins: Array.isArray(line.plugins)
            ? line.plugins.map((entry) => ({
                name: asString(asRecord(entry).name) ?? "",
                version: asString(asRecord(entry).version),
                source: asString(asRecord(entry).source) ?? "",
              }))
            : [],
          permissionMode: asString(line.permissionMode),
          version: asString(line.claude_code_version),
          outputStyle: asString(line.output_style),
          initIndex: this.initCount,
        }
        const previous = this.lastSession
        this.lastSession = session
        this.initCount += 1

        const events = [this.build({ type: "session_started", session }, sessionId, path, ts, raw)]
        // A resumed run with `--model` looks exactly like this and nothing else
        // announces it, so the change is derived from two inits or not seen.
        // A change is only a change when both sides said something.
        if (
          previous !== null &&
          previous.sessionId === sessionId &&
          previous.model !== null &&
          session.model !== null &&
          previous.model !== session.model
        ) {
          events.push(this.build({ type: "model_changed", from: previous.model, to: session.model }, sessionId, path, ts, raw))
        }
        return events
      }

      case ClaudeSystemSubtype.Status:
        return this.wrap(
          { type: "status_changed", status: asString(line.status), permissionMode: asString(line.permissionMode) },
          sessionId,
          path,
          ts,
          raw,
        )

      case ClaudeSystemSubtype.TaskSummary: {
        const detail = asString(line.detail)
        return detail === null ? [] : this.wrap({ type: "activity", detail }, sessionId, path, ts, raw)
      }

      case ClaudeSystemSubtype.TaskStarted: {
        const callId = asString(line.tool_use_id) ?? ""
        return this.wrap(
          {
            type: "task_started",
            taskId: asString(line.task_id) ?? "",
            callId,
            taskKind: claudeTaskKind(asString(line.task_type)),
            label: asString(line.subagent_type) ?? asString(line.workflow_name),
            description: asString(line.description) ?? "",
            prompt: asString(line.prompt),
            // Claude names no transcript for a delegated run. A subagent's
            // sits on disk under a path derived from the session, which
            // `claude/store` works out; a workflow agent's is watchable only.
            transcriptId: null,
          },
          sessionId,
          path,
          ts,
          raw,
        )
      }

      case ClaudeSystemSubtype.TaskProgress: {
        const progress = this.build(
          {
            type: "task_progress",
            taskId: asString(line.task_id) ?? "",
            callId: asString(line.tool_use_id) ?? "",
            description: asString(line.description) ?? "",
            lastTool: asString(line.last_tool_name),
            usage: taskUsage(asRecord(line.usage)),
          },
          sessionId,
          path,
          ts,
          raw,
        )
        // The board rides along on only *some* progress lines, so a consumer
        // keeps the last one it saw rather than expecting one per update.
        const phases = readWorkflowProgress(line.workflow_progress)
        if (phases === null) return [progress]
        return [
          progress,
          this.build(
            {
              type: "workflow_progress",
              taskId: asString(line.task_id) ?? "",
              callId: asString(line.tool_use_id) ?? "",
              phases,
            },
            sessionId,
            path,
            ts,
            raw,
          ),
        ]
      }

      case ClaudeSystemSubtype.TaskNotification:
        return this.wrap(
          {
            type: "task_completed",
            taskId: asString(line.task_id) ?? "",
            callId: asString(line.tool_use_id),
            status: asString(line.status) ?? "completed",
            summary: asString(line.summary),
            usage: taskUsage(asRecord(line.usage)),
          },
          sessionId,
          path,
          ts,
          raw,
        )

      // `task_updated` carries only a status patch the notification repeats, so
      // it earns no row of its own — but it is the only completion signal a
      // task that never notifies will send, so it is mapped, not dropped.
      case ClaudeSystemSubtype.TaskUpdated: {
        const patch = asRecord(line.patch)
        const status = asString(patch.status)
        return status === null
          ? []
          : this.wrap(
              { type: "task_completed", taskId: asString(line.task_id) ?? "", callId: null, status, summary: null, usage: null },
              sessionId,
              path,
              ts,
              raw,
            )
      }

      case ClaudeSystemSubtype.BackgroundTasksChanged:
        return this.wrap(
          {
            type: "background_tasks_changed",
            tasks: Array.isArray(line.tasks)
              ? line.tasks.map((entry) => ({
                  taskId: asString(asRecord(entry).task_id) ?? "",
                  description: asString(asRecord(entry).description) ?? "",
                }))
              : [],
          },
          sessionId,
          path,
          ts,
          raw,
        )

      case ClaudeSystemSubtype.ThinkingTokens: {
        const tokens = asNumber(line.estimated_tokens)
        return tokens === null ? [] : this.wrap({ type: "thinking_progress", tokens }, sessionId, path, ts, raw)
      }

      case ClaudeSystemSubtype.HookStarted:
      case ClaudeSystemSubtype.HookResponse:
        return this.wrap(
          {
            type: "hook",
            phase: subtype === ClaudeSystemSubtype.HookStarted ? "started" : "finished",
            name: asString(line.hook_name) ?? "",
            event: asString(line.hook_event) ?? "",
            outcome: asString(line.outcome),
            exitCode: asNumber(line.exit_code),
          },
          sessionId,
          path,
          ts,
          raw,
        )

      case ClaudeSystemSubtype.PostTurnSummary:
        return this.wrap(
          {
            type: "post_turn_summary",
            category: asString(line.status_category) ?? "",
            detail: asString(line.status_detail) ?? "",
            needsAction: asString(line.needs_action) === "" ? null : asString(line.needs_action),
          },
          sessionId,
          path,
          ts,
          raw,
        )

      case ClaudeSystemSubtype.CompactBoundary: {
        const meta = asRecord(line.compact_metadata)
        return this.wrap(
          {
            type: "context_compacted",
            trigger: asString(meta.trigger),
            preTokens: asNumber(meta.pre_tokens),
            postTokens: asNumber(meta.post_tokens),
            droppedTokens: asNumber(meta.cumulative_dropped_tokens),
            durationMs: asNumber(meta.duration_ms),
          },
          sessionId,
          path,
          ts,
          raw,
        )
      }

      case ClaudeSystemSubtype.PermissionDenied:
        return this.wrap(
          {
            type: "permission_denied",
            callId: asString(line.tool_use_id) ?? "",
            toolName: asString(line.tool_name) ?? "",
            message: asString(line.message) ?? "",
          },
          sessionId,
          path,
          ts,
          raw,
        )

      default:
        return this.wrap({ type: "unknown", wireType: "system", subtype }, sessionId, path, ts, raw)
    }
  }

  /**
   * Maps one SSE frame.
   *
   * Everything here is *read* rather than asserted. The wire types describe the
   * shapes a well-formed frame has; a truncated or reordered line is not
   * well-formed, and a cast would turn that into a crash inside the mapper —
   * ending the transcript over one bad line, which is exactly what this parser
   * exists to avoid.
   */
  private mapStreamFrame(frame: WireStreamFrame, path: AgentPath): AgentEventPayload | null {
    const fields = asRecord(frame as unknown as JsonValue)
    const thread = pathKey(path)

    switch (frame.type) {
      case ClaudeStreamFrameType.MessageStart: {
        const id = asString(asRecord(fields.message).id)
        // No id means no join key for the blocks that follow, so the preview is
        // skipped entirely rather than attached to whatever message was open.
        if (id === null) return null
        // A message's block count is dead the moment the next one opens on the
        // same thread — the CLI never revisits a committed message — so it is
        // dropped here rather than accreting an entry per message for the life
        // of the session.
        const previous = this.openMessage.get(thread)
        if (previous !== undefined && previous !== id) this.committedBlocks.delete(`${thread}\u0000${previous}`)
        this.openMessage.set(thread, id)
        return null
      }

      case ClaudeStreamFrameType.ContentBlockStart: {
        const block = this.blockRef(thread, asNumber(fields.index))
        if (block === null) return null
        const content = asRecord(fields.content_block)
        const contentType = asString(content.type)
        if (contentType === ClaudeContentBlockType.Text) {
          return { type: "delta", delta: "block_start", block, blockType: "text" }
        }
        if (contentType === ClaudeContentBlockType.Thinking) {
          return { type: "delta", delta: "block_start", block, blockType: "thinking" }
        }
        if (contentType === ClaudeContentBlockType.ToolUse) {
          const toolId = asString(content.id)
          const toolName = asString(content.name)
          // A tool block without both is not a labelable call, and the payload
          // promises both together — so it degrades to an unlabelled block
          // rather than a half-built one.
          if (toolId === null || toolName === null) {
            return { type: "delta", delta: "block_start", block, blockType: "text" }
          }
          return { type: "delta", delta: "block_start", block, blockType: "tool_use", toolId, toolName }
        }
        // An unknown block kind is skipped rather than guessed: the committed
        // line still carries the content, so nothing is lost but the preview.
        return null
      }

      case ClaudeStreamFrameType.ContentBlockDelta: {
        const block = this.blockRef(thread, asNumber(fields.index))
        if (block === null) return null
        const delta = asRecord(fields.delta)
        const deltaType = asString(delta.type)

        if (deltaType === ClaudeContentDeltaType.Text) {
          const text = asString(delta.text)
          return text === null ? null : { type: "delta", delta: "text", block, text }
        }
        // Thinking text rides the same shape; `block_start` already said which
        // kind the block is, so a second variant would only repeat it.
        if (deltaType === ClaudeContentDeltaType.Thinking) {
          const text = asString(delta.thinking)
          return text === null ? null : { type: "delta", delta: "text", block, text }
        }
        if (deltaType === ClaudeContentDeltaType.InputJson) {
          const partialJson = asString(delta.partial_json)
          return partialJson === null ? null : { type: "delta", delta: "input", block, partialJson }
        }
        // `signature_delta` signs the thinking block; it is not display content.
        return null
      }

      case ClaudeStreamFrameType.ContentBlockStop: {
        const block = this.blockRef(thread, asNumber(fields.index))
        return block === null ? null : { type: "delta", delta: "block_stop", block }
      }

      // The committed `assistant` and `result` lines carry these facts already.
      default:
        return null
    }
  }

  private mapAssistant(
    line: Record<string, JsonValue>,
    sessionId: string,
    path: AgentPath,
    ts: string | null,
    raw: JsonValue,
  ): readonly AgentEvent[] {
    const message = asRecord(line.message)
    const messageId = asString(message.id) ?? "unknown"
    const blocks = Array.isArray(message.content) ? message.content : []
    const events: AgentEvent[] = []

    for (const entry of blocks) {
      const block = asRecord(entry)
      // Committed lines carry no index; it is derived by counting blocks per
      // message id in arrival order, which is what joins them to their deltas.
      const ref = this.nextBlockRef(pathKey(path), messageId)
      const type = asString(block.type)

      if (type === ClaudeContentBlockType.Text) {
        events.push(this.build({ type: "assistant_text", text: asString(block.text) ?? "", block: ref }, sessionId, path, ts, raw))
        continue
      }
      if (type === ClaudeContentBlockType.Thinking) {
        events.push(this.build({ type: "reasoning", text: asString(block.thinking) ?? "", block: ref }, sessionId, path, ts, raw))
        continue
      }
      if (type === ClaudeContentBlockType.ToolUse) {
        const callId = asString(block.id) ?? ""
        const name = asString(block.name) ?? ""
        const input = block.input ?? {}
        // A call made *here* is the parent of anything that call spawns, so the
        // path for its children is this path plus the call itself. This is what
        // makes a subagent inside a subagent nest instead of flattening.
        this.pathByCall.set(callId, [...path, callId])
        events.push(
          this.build(
            { type: "tool_call_started", callId, name, kind: toolKind(name), input, title: toolTitle(name, input) },
            sessionId,
            path,
            ts,
            raw,
          ),
        )
        // The plan is an argument to a tool call, not an event of its own, so
        // it is lifted here — a consumer should never have to reach into tool
        // input to draw the agent's plan.
        const planEvent = this.mapPlanCall(callId, name, input, sessionId, path, ts, raw)
        if (planEvent !== null) events.push(planEvent)
      }
    }

    return events
  }

  private mapUser(
    line: Record<string, JsonValue>,
    sessionId: string,
    path: AgentPath,
    ts: string | null,
    raw: JsonValue,
  ): readonly AgentEvent[] {
    const message = asRecord(line.message)
    const content = message.content
    const synthetic = line.isSynthetic === true || line.isReplay === true

    // A `user` line's content is one of two unrelated shapes with nothing
    // labelling which: a bare string is the human's prompt, an array is what
    // the CLI fed back. The shape is the discriminator.
    const typed = asString(content)
    if (typed !== null) {
      return this.wrap({ type: "user_message", text: typed, synthetic }, sessionId, path, ts, raw)
    }
    if (!Array.isArray(content)) return []

    const events: AgentEvent[] = []
    for (const entry of content) {
      const block = asRecord(entry)
      const type = asString(block.type)
      if (type === ClaudeContentBlockType.ToolResult) {
        const callId = asString(block.tool_use_id) ?? ""
        const result = readToolResult(block, line.tool_use_result)
        events.push(this.build({ type: "tool_call_completed", callId, result }, sessionId, path, ts, raw))
        const settled = this.settlePlanStep(callId, result.text)
        if (settled !== null) events.push(this.build(settled, sessionId, path, ts, raw))
        continue
      }
      if (type === ClaudeContentBlockType.Text) {
        const text = asString(block.text) ?? ""
        if (text.startsWith(INTERRUPT_PREFIX)) {
          events.push(this.build({ type: "error", message: text }, sessionId, path, ts, raw))
          continue
        }
        // Marked synthetic whatever the flags say. A human prompt arrives as
        // the bare-string shape; a text block inside the array shape is the CLI
        // feeding the model — a delegated run's brief, an injected reminder —
        // and treating it as a prompt opens a phantom turn whose header is text
        // the reader never wrote.
        events.push(this.build({ type: "user_message", text, synthetic: true }, sessionId, path, ts, raw))
      }
    }
    return events
  }

  private mapResult(
    line: Record<string, JsonValue>,
    sessionId: string,
    path: AgentPath,
    ts: string | null,
    raw: JsonValue,
  ): readonly AgentEvent[] {
    const terminalReason = asString(line.terminal_reason)
    const isError = line.is_error === true
    const status = isError ? "error" : terminalReason === "interrupted" ? "interrupted" : "completed"
    return this.wrap(
      {
        type: "turn_completed",
        status,
        stopReason: asString(line.stop_reason),
        terminalReason,
        finalText: asString(line.result),
        usage: normalizeUsage(line.usage, asNumber(line.total_cost_usd)),
        durationMs: asNumber(line.duration_ms),
        numTurns: asNumber(line.num_turns),
        permissionDenials: asArray(line.permission_denials).map((entry) => {
          const denial = asRecord(entry)
          return {
            toolName: asString(denial.tool_name) ?? "",
            callId: asString(denial.tool_use_id) ?? "",
            input: denial.tool_input ?? null,
          }
        }),
      },
      sessionId,
      path,
      ts,
      raw,
    )
  }

  /**
   * Folds a plan-tool call into the running plan.
   *
   * `TodoWrite` republishes everything, so it simply replaces. `TaskCreate`
   * cannot publish yet — the step has no id until its result comes back — so it
   * is parked and settled in `settlePlanStep`. `TaskUpdate` patches in place.
   */
  private mapPlanCall(
    callId: string,
    name: string,
    input: JsonValue,
    sessionId: string,
    path: AgentPath,
    ts: string | null,
    raw: JsonValue,
  ): AgentEvent | null {
    if (name === "TodoWrite") {
      const steps = readPlan(input)
      if (steps === null) return null
      this.planSteps = [...steps]
      return this.build({ type: "plan_updated", steps: this.planSteps }, sessionId, path, ts, raw)
    }

    const argument = asRecord(input)
    if (name === "TaskCreate") {
      const content = asString(argument.subject) ?? asString(argument.description)
      if (content === null) return null
      this.pendingPlanSteps.set(callId, {
        id: null,
        content,
        status: "pending",
        ...(asString(argument.activeForm) !== null ? { activeForm: asString(argument.activeForm)! } : {}),
      })
      return null
    }

    if (name === "TaskUpdate") {
      const id = asString(argument.taskId) ?? (asNumber(argument.taskId) === null ? null : String(asNumber(argument.taskId)))
      if (id === null) return null
      // An update that names no status is a rename, so the step keeps the one
      // it has rather than being reset to pending.
      const status = argument.status === undefined ? null : claudePlanStatus(asString(argument.status))
      this.planSteps = this.planSteps.map((step) =>
        step.id !== id
          ? step
          : { ...step, content: asString(argument.subject) ?? step.content, status: status ?? step.status },
      )
      return this.build({ type: "plan_updated", steps: this.planSteps }, sessionId, path, ts, raw)
    }

    return null
  }

  /** Attaches the id a `TaskCreate` result carries, which is what makes the step patchable. */
  private settlePlanStep(callId: string, resultText: string): AgentEventPayload | null {
    const pending = this.pendingPlanSteps.get(callId)
    if (pending === undefined) return null
    this.pendingPlanSteps.delete(callId)
    const match = CREATED_ID.exec(resultText)
    // Falling back to position keeps the step visible when the wording moves.
    // The sentinel prefix keeps it out of the wire's own id space, so a later
    // TaskUpdate for the real step "3" cannot also patch a guessed "3".
    const id = match === null ? `local:${this.planSteps.length + 1}` : match[1]!
    this.planSteps = [...this.planSteps, { ...pending, id }]
    return { type: "plan_updated", steps: this.planSteps }
  }

  /**
   * The path an event with this `parent_tool_use_id` belongs to.
   *
   * Resolved through the call that spawned it, so depth accumulates: a call
   * made inside a subagent already has that subagent's path recorded, and the
   * fallback covers a capture that starts mid-run with the spawning call
   * already off the top of the log.
   */
  private pathOf(parentToolUseId: JsonValue | undefined): AgentPath {
    const id = asString(parentToolUseId)
    if (id === null) return []
    return this.pathByCall.get(id) ?? [id]
  }

  private nextBlockRef(thread: string, messageId: string): BlockRef {
    const key = `${thread}\u0000${messageId}`
    const index = this.committedBlocks.get(key) ?? 0
    this.committedBlocks.set(key, index + 1)
    return { messageId, index }
  }

  /**
   * Null rather than a placeholder: `BlockRef` is a join key, and a wrong one
   * attaches streamed text to the wrong block — silently. A frame with no
   * readable index has no join key at all, so it produces no preview.
   */
  private blockRef(thread: string, index: number | null): BlockRef | null {
    const messageId = this.openMessage.get(thread)
    if (messageId === undefined || index === null) return null
    return { messageId, index }
  }

  private wrap(
    payload: AgentEventPayload | null,
    sessionId: string,
    path: AgentPath,
    ts: string | null,
    raw: JsonValue,
  ): readonly AgentEvent[] {
    return payload === null ? [] : [this.build(payload, sessionId, path, ts, raw)]
  }

  private build(
    payload: AgentEventPayload,
    sessionId: string,
    path: AgentPath,
    ts: string | null,
    raw: JsonValue,
  ): AgentEvent {
    const seq = this.seq
    this.seq += 1
    return { id: `${sessionId}:${seq}`, sessionId, seq, ts, agentPath: path, payload, raw }
  }
}

/**
 * Reads a workflow's progress board.
 *
 * The wire sends one flat array mixing `workflow_phase` and `workflow_agent`
 * entries, each agent naming its phase by index; this rebuilds the nesting the
 * flat list implies. Phases with no agents yet are kept — a phase that has been
 * declared but not reached is part of the picture.
 */
function readWorkflowProgress(value: JsonValue | undefined): readonly WorkflowPhaseProgress[] | null {
  if (!Array.isArray(value)) return null

  const phases = new Map<number, { index: number; title: string; agents: WorkflowAgentProgress[] }>()
  const orphans: WorkflowAgentProgress[] = []

  for (const item of value) {
    const entry = asRecord(item)
    if (asString(entry.type) === "workflow_phase") {
      const index = asNumber(entry.index) ?? 0
      const existing = phases.get(index)
      if (existing === undefined) {
        phases.set(index, { index, title: asString(entry.title) ?? `Phase ${index}`, agents: [] })
      }
      continue
    }
    if (asString(entry.type) !== "workflow_agent") continue

    const agent: WorkflowAgentProgress = {
      index: asNumber(entry.index) ?? 0,
      label: asString(entry.label) ?? "agent",
      phaseIndex: asNumber(entry.phaseIndex) ?? 0,
      phaseTitle: asString(entry.phaseTitle) ?? "",
      agentId: asString(entry.agentId),
      model: asString(entry.model),
      state: asString(entry.state) ?? "unknown",
      queuedAt: asNumber(entry.queuedAt),
      startedAt: asNumber(entry.startedAt),
      attempt: asNumber(entry.attempt),
      promptPreview: asString(entry.promptPreview),
      resultPreview: asString(entry.resultPreview),
      tokens: asNumber(entry.tokens),
      toolCalls: asNumber(entry.toolCalls),
      durationMs: asNumber(entry.durationMs),
    }
    const phase = phases.get(agent.phaseIndex)
    if (phase === undefined) orphans.push(agent)
    else phase.agents.push(agent)
  }

  // An agent whose phase never appeared still belongs on screen; it gets a
  // phase built from the title it names.
  for (const agent of orphans) {
    const phase = phases.get(agent.phaseIndex)
    if (phase === undefined) {
      phases.set(agent.phaseIndex, {
        index: agent.phaseIndex,
        title: agent.phaseTitle === "" ? `Phase ${agent.phaseIndex}` : agent.phaseTitle,
        agents: [agent],
      })
    } else phase.agents.push(agent)
  }

  if (phases.size === 0) return null
  return [...phases.values()]
    .sort((a, b) => a.index - b.index)
    .map((phase) => ({ ...phase, agents: [...phase.agents].sort((a, b) => a.index - b.index) }))
}

/**
 * A delegated run's usage, which is a total and nothing else.
 *
 * The breakdown stays null rather than zero: the wire reports one figure here,
 * and zeros would read as "no input tokens" — a claim the line never made.
 */
function taskUsage(usage: Record<string, JsonValue>): Usage | null {
  const total = asNumber(usage.total_tokens)
  if (total === null) return null
  return {
    totalTokens: total,
    inputTokens: null,
    outputTokens: null,
    cacheReadTokens: null,
    cacheCreationTokens: null,
    reasoningTokens: null,
  }
}

/** Maps a whole capture in one pass, for a persisted log or a fixture. */
export function mapClaudeStream(text: string, options?: MapperOptions): readonly AgentEvent[] {
  const mapper = new ClaudeStreamMapper(options)
  const events: AgentEvent[] = []
  for (const line of text.split("\n")) {
    if (line.trim().length === 0) continue
    events.push(...mapper.push(line))
  }
  return events
}

/** @responsibility Classifies harness tool names and summarizes one call's arguments for a transcript row. */

import type { ToolKind } from "../events"
import { asRecord, asString, shortenPath } from "../json"
import type { JsonValue } from "./wire"

const KINDS: ReadonlyArray<readonly [ToolKind, ReadonlySet<string>]> = [
  ["shell", new Set(["Bash", "BashOutput", "KillShell", "shell", "local_shell_call"])],
  ["file_read", new Set(["Read", "NotebookRead", "view"])],
  ["file_edit", new Set(["Edit", "Write", "NotebookEdit", "MultiEdit", "apply_patch"])],
  ["search", new Set(["Glob", "Grep", "ToolSearch", "SearchSkills", "SearchPlugins"])],
  ["web", new Set(["WebFetch", "WebSearch"])],
  ["plan", new Set(["TodoWrite", "ExitPlanMode", "EnterPlanMode"])],
  ["subagent", new Set(["Task", "Agent"])],
  ["workflow", new Set(["Workflow"])],
]

/**
 * Maps a tool name to its rendering hint.
 *
 * Name-based rather than shape-based on purpose: the wire gives no kind, and a
 * name is stable in a way that argument shapes are not. Anything unrecognized —
 * including every MCP tool past the `mcp__` prefix — falls through to a kind
 * that must still render.
 */
export function toolKind(name: string): ToolKind {
  if (name.startsWith("mcp__")) return "mcp"
  for (const [kind, names] of KINDS) if (names.has(name)) return kind
  return "other"
}

/** One string argument off a tool's input, or null when it is absent or another shape. */
function field(input: JsonValue, key: string): string | null {
  return asString(asRecord(input)[key])
}

export { shortenPath } from "../json"

/**
 * One line naming what a call does, from its own arguments.
 *
 * Derived at map time rather than at render time so the summary travels with
 * the event — a consumer replaying a persisted log gets the same row without
 * re-deriving it, and a tool whose arguments never finished streaming still has
 * something to show.
 */
export function toolTitle(name: string, input: JsonValue): string {
  const kind = toolKind(name)
  switch (kind) {
    case "shell": {
      const description = field(input, "description")
      const command = field(input, "command")
      return description ?? (command === null ? name : command.split("\n")[0]!)
    }
    case "file_read":
    case "file_edit": {
      const path = field(input, "file_path") ?? field(input, "path") ?? field(input, "notebook_path")
      return path === null ? name : shortenPath(path)
    }
    case "search": {
      const pattern = field(input, "pattern") ?? field(input, "query")
      return pattern === null ? name : pattern
    }
    case "web": {
      const url = field(input, "url")
      const query = field(input, "query")
      return url ?? query ?? name
    }
    case "subagent": {
      const description = field(input, "description")
      const type = field(input, "subagent_type")
      if (description !== null && type !== null) return `${type}: ${description}`
      return description ?? type ?? name
    }
    case "workflow":
      return field(input, "name") ?? "Workflow"
    case "plan":
      return "Updated plan"
    case "mcp": {
      const [, server, tool] = name.split("__")
      return tool === undefined ? name : `${server}: ${tool}`
    }
    default:
      return name
  }
}

/** The verb a row uses for a tool, in the tense its status calls for. */
export function toolVerb(name: string, running: boolean): string {
  switch (toolKind(name)) {
    case "shell":
      return running ? "Running" : "Ran"
    case "file_read":
      return running ? "Reading" : "Read"
    case "file_edit":
      return running ? "Editing" : "Edited"
    case "search":
      return running ? "Searching" : "Searched"
    case "web":
      return running ? "Fetching" : "Fetched"
    case "subagent":
      return running ? "Delegating" : "Delegated"
    case "workflow":
      return running ? "Orchestrating" : "Orchestrated"
    case "plan":
      return running ? "Planning" : "Planned"
    default:
      return running ? "Calling" : "Called"
  }
}

/** @responsibility Derives what a session can do — commands, skills, agents, tools and MCP servers — for a composer's pickers. */

import type {
  AgentCapabilities,
  CapabilityCommand,
  CapabilityServer,
  CapabilityTool,
} from "../capabilities"
import type { AgentEvent, SessionInfo } from "../events"
import { toolKind } from "./tools"

/**
 * The prefix an MCP tool carries, normalized for comparison against a server's
 * display name.
 *
 * The two disagree on purpose: a server named "example Mail" contributes
 * `mcp__example_Mail__get_message`, so matching them means flattening both
 * sides to the same alphabet rather than comparing strings.
 */
function slug(value: string): string {
  return value.toLowerCase().replace(/[^a-z0-9]+/g, "")
}

/** Splits `mcp__server__tool` into its server, or null for a first-party tool. */
export function mcpServerOf(toolName: string): string | null {
  if (!toolName.startsWith("mcp__")) return null
  const rest = toolName.slice("mcp__".length)
  const separator = rest.indexOf("__")
  return separator === -1 ? rest : rest.slice(0, separator)
}

function classifyCommand(name: string, skills: ReadonlySet<string>): CapabilityCommand {
  const [head, tail] = name.split(":")
  if (tail !== undefined) return { name, source: "plugin", plugin: head! }
  if (skills.has(name)) return { name, source: "skill", plugin: null }
  return { name, source: "session", plugin: null }
}

/**
 * Folds every `init` in a log into one description of the session.
 *
 * Merged rather than replaced, because the tool list **grows between inits**:
 * deferred tools load on demand, so the last `init` is not a superset of the
 * first in any guaranteed way and treating either one as the answer loses
 * entries. What the first init did *not* carry is reported as `deferred`, which
 * is the only signal the stream gives that a tool arrived late.
 */
export function sessionCapabilities(events: readonly AgentEvent[]): AgentCapabilities | null {
  const inits: SessionInfo[] = []
  for (const event of events) {
    if (event.payload.type === "session_started") inits.push(event.payload.session)
  }
  if (inits.length === 0) return null

  const first = inits[0]!
  const latest = inits[inits.length - 1]!
  const firstTools = new Set(first.tools)

  const toolNames = new Set<string>()
  for (const init of inits) for (const name of init.tools) toolNames.add(name)

  const tools: CapabilityTool[] = [...toolNames].map((name) => ({
    name,
    kind: toolKind(name),
    server: mcpServerOf(name),
    deferred: !firstTools.has(name),
  }))

  const servers = new Map<string, CapabilityServer>()
  for (const init of inits) {
    for (const server of init.mcpServers) {
      const matched = tools.filter((tool) => tool.server !== null && slug(tool.server) === slug(server.name))
      servers.set(server.name, {
        name: server.name,
        status: server.status,
        connected: server.status === "connected",
        tools: matched.map((tool) => tool.name),
      })
    }
  }

  const skills = new Set<string>()
  for (const init of inits) for (const skill of init.skills) skills.add(skill)

  const commands = new Map<string, CapabilityCommand>()
  for (const init of inits) {
    for (const name of init.slashCommands) commands.set(name, classifyCommand(name, skills))
    for (const name of init.terminalSlashCommands) commands.set(name, { name, source: "terminal", plugin: null })
  }

  const agents = new Set<string>()
  for (const init of inits) for (const agent of init.agents) agents.add(agent)

  return {
    sessionId: latest.sessionId,
    model: latest.model,
    cwd: latest.cwd,
    permissionMode: latest.permissionMode,
    commands: [...commands.values()],
    skills: [...skills].map((name) => ({ name, description: null })),
    agents: [...agents],
    tools,
    mcpServers: [...servers.values()],
    plugins: latest.plugins.map((plugin) => ({
      name: plugin.name,
      version: plugin.version,
      source: plugin.source,
    })),
    // Null rather than empty: the CLI does not advertise the models a session
    // could switch to, or the catalogues a plugin came from, so a picker omits
    // those sections here rather than showing them bare.
    models: null,
    pluginSources: null,
    hooks: null,
  }
}

/** Groups tools for a picker: first-party tools by kind, MCP tools by their server. */
export function groupTools(capabilities: AgentCapabilities): ReadonlyMap<string, readonly CapabilityTool[]> {
  const groups = new Map<string, CapabilityTool[]>()
  for (const tool of capabilities.tools ?? []) {
    const key = tool.server === null ? tool.kind : `mcp:${tool.server}`
    const bucket = groups.get(key)
    if (bucket === undefined) groups.set(key, [tool])
    else bucket.push(tool)
  }
  return groups
}

/** @responsibility Locates the transcripts Claude Code writes to disk, which is where a delegated run's own conversation lives. */

import { asNumber, asRecord, asString } from "../json"
import type { JsonValue } from "./wire"

/**
 * Where one session's files live.
 *
 * Pure path arithmetic, no filesystem access: this module runs in the browser
 * as readily as in a host process, and reading the files is the host's job.
 */
export interface SessionLocation {
  /** Usually `~/.claude/projects`. */
  readonly projectsDir: string
  /** The session's working directory, which is what the project folder is named after. */
  readonly cwd: string
  /** From `system/init`, and stable across a resume. */
  readonly sessionId: string
}

/**
 * The project folder's name, derived from the working directory.
 *
 * Every character that cannot appear in a flat folder name becomes `-`, so
 * `/tmp/my_app` becomes `-tmp-my-app`. The rule is inferred from observed
 * directories rather than documented, so a host that can list `projectsDir`
 * should prefer matching an existing folder over trusting this.
 */
export function projectSlug(cwd: string): string {
  return cwd.replace(/[^a-zA-Z0-9]/g, "-")
}

/** The folder holding every session for this working directory. */
export function projectDir(location: SessionLocation): string {
  return `${location.projectsDir}/${projectSlug(location.cwd)}`
}

/** The main conversation's own log — the same shapes the stream carries, minus the deltas. */
export function sessionTranscriptPath(location: SessionLocation): string {
  return `${projectDir(location)}/${location.sessionId}.jsonl`
}

/** The per-session folder holding everything the session spawned. */
export function sessionDir(location: SessionLocation): string {
  return `${projectDir(location)}/${location.sessionId}`
}

/**
 * A subagent's full transcript, named by the `task_id` the wire already gave
 * you on `system/task_started`.
 *
 * This is the conversation the stream refuses to carry: the subagent's prompt,
 * every tool call it made, and its final message — all in the same line shapes
 * the stream uses, so the same parser reads it.
 */
export function subagentTranscriptPath(location: SessionLocation, taskId: string): string {
  return `${sessionDir(location)}/subagents/agent-${taskId}.jsonl`
}

/** A subagent's metadata sidecar, which names the tool call that spawned it. */
export function subagentMetaPath(location: SessionLocation, taskId: string): string {
  return `${sessionDir(location)}/subagents/agent-${taskId}.meta.json`
}

/** The folder of workflow run records. Each file is `<runId>.json`. */
export function workflowsDir(location: SessionLocation): string {
  return `${sessionDir(location)}/workflows`
}

/**
 * One workflow run's record: its script, phases, per-agent progress, result and
 * totals.
 *
 * Keyed by `runId`, which is **not on the wire** — the stream reports a
 * `task_id` instead. Read the records in [`workflowsDir`] and match on their
 * own `taskId` field; [`workflowRunTaskId`] pulls it out.
 */
export function workflowRunPath(location: SessionLocation, runId: string): string {
  return `${workflowsDir(location)}/${runId}.json`
}

/** One workflow agent's full transcript, named by the `agentId` from the progress board. */
export function workflowAgentTranscriptPath(
  location: SessionLocation,
  runId: string,
  agentId: string,
): string {
  return `${sessionDir(location)}/subagents/workflows/${runId}/agent-${agentId}.jsonl`
}

/** A workflow run's journal: one line per agent start and result, in completion order. */
export function workflowJournalPath(location: SessionLocation, runId: string): string {
  return `${sessionDir(location)}/subagents/workflows/${runId}/journal.jsonl`
}

/** What a subagent's `.meta.json` says. */
export interface SubagentMeta {
  readonly agentType: string | null
  readonly description: string | null
  /** The spawning tool call's id — the same `callId` the stream reported. */
  readonly toolUseId: string | null
  /** How deep the run sits. `1` is a subagent of the main thread. */
  readonly spawnDepth: number | null
}

export function parseSubagentMeta(json: string): SubagentMeta | null {
  let decoded: unknown
  try {
    decoded = JSON.parse(json)
  } catch {
    return null
  }
  const meta = asRecord(decoded as JsonValue)
  return {
    agentType: asString(meta.agentType),
    description: asString(meta.description),
    toolUseId: asString(meta.toolUseId),
    spawnDepth: asNumber(meta.spawnDepth),
  }
}

/** The `task_id` a workflow run record names, for matching a record to a run seen on the stream. */
export function workflowRunTaskId(json: string): string | null {
  try {
    return asString(asRecord(JSON.parse(json) as JsonValue).taskId)
  } catch {
    return null
  }
}

/** One line of a workflow's journal. */
export interface WorkflowJournalEntry {
  readonly type: string
  readonly agentId: string
  /** Present on a `result` line: what that agent returned, whole rather than previewed. */
  readonly result: JsonValue | null
}

/**
 * Reads a workflow's journal.
 *
 * The board on the stream previews each agent's result; this carries it in
 * full, which is what a host reaches for when a preview is not enough and the
 * agent's own transcript is more than the reader asked for.
 */
export function parseWorkflowJournal(text_: string): readonly WorkflowJournalEntry[] {
  const entries: WorkflowJournalEntry[] = []
  for (const line of text_.split("\n")) {
    if (line.trim().length === 0) continue
    let decoded: unknown
    try {
      decoded = JSON.parse(line)
    } catch {
      continue
    }
    const entry = asRecord(decoded as JsonValue)
    const agentId = asString(entry.agentId)
    if (agentId === null) continue
    entries.push({ type: asString(entry.type) ?? "unknown", agentId, result: entry.result ?? null })
  }
  return entries
}

/**
 * A pointer to one conversation on disk.
 *
 * The unit a host opens: enough to name the thing in a list, find its bytes,
 * and — when the path cannot be built yet — say what is missing instead of
 * silently producing a path that resolves to nothing.
 */
export interface TranscriptRef {
  readonly kind: "session" | "subagent" | "workflow_agent"
  /** What to call it in a list of open transcripts. */
  readonly label: string
  /** The id this transcript is addressed by: a `task_id` or an `agentId`. */
  readonly key: string
  /** The spawning tool call, where one exists, so a ref links back to its row. */
  readonly callId: string | null
  /** Absolute path, or null when [`resolved`](Self::resolved) is false. */
  readonly path: string | null
  /** False when something must be looked up before the path can be built. */
  readonly resolved: boolean
  /** What the host has to do to resolve it. Null once resolved. */
  readonly blockedBy: string | null
}

/** Derives a session's location from its own `init`, so a host supplies only the projects directory. */
export function sessionLocationOf(
  projectsDir: string,
  session: { readonly cwd: string | null; readonly sessionId: string },
): SessionLocation | null {
  // The project folder is named after the working directory, so a session that
  // never reported one cannot be addressed on disk. Null says that plainly
  // rather than building a path rooted at an empty string.
  if (session.cwd === null || session.cwd === "") return null
  return { projectsDir, cwd: session.cwd, sessionId: session.sessionId }
}

/** Where a subagent's conversation lives. Always resolvable: the wire gave the `task_id` up front. */
export function subagentTranscriptRef(
  location: SessionLocation,
  run: { readonly taskId: string | null; readonly callId: string; readonly label: string | null },
): TranscriptRef {
  if (run.taskId === null) {
    return {
      kind: "subagent",
      label: run.label ?? "Subagent",
      key: run.callId,
      callId: run.callId,
      path: null,
      resolved: false,
      blockedBy: "no task id yet — the run has not reported task_started",
    }
  }
  return {
    kind: "subagent",
    label: run.label ?? "Subagent",
    key: run.taskId,
    callId: run.callId,
    path: subagentTranscriptPath(location, run.taskId),
    resolved: true,
    blockedBy: null,
  }
}

/**
 * Where one workflow agent's conversation lives.
 *
 * `runId` is the catch: it is never on the stream, so a caller that has not
 * matched a record in [`workflowsDir`] gets an unresolved ref naming exactly
 * that, rather than a plausible path that leads nowhere.
 */
export function workflowAgentTranscriptRef(
  location: SessionLocation,
  runId: string | null,
  agent: { readonly agentId: string | null; readonly label: string; readonly index: number },
  callId: string | null = null,
): TranscriptRef {
  const key = agent.agentId
  if (key === null) {
    return {
      kind: "workflow_agent",
      label: agent.label,
      key: String(agent.index),
      callId,
      path: null,
      resolved: false,
      blockedBy: "the agent has not started, so it has no id yet",
    }
  }
  if (runId === null) {
    return {
      kind: "workflow_agent",
      label: agent.label,
      key,
      callId,
      path: null,
      resolved: false,
      blockedBy: `run id unknown — read ${workflowsDir(location)} and match a record whose taskId is this run's`,
    }
  }
  return {
    kind: "workflow_agent",
    label: agent.label,
    key,
    callId,
    path: workflowAgentTranscriptPath(location, runId, key),
    resolved: true,
    blockedBy: null,
  }
}

/**
 * Every conversation this session produced, as pointers.
 *
 * One list, main thread included, so a host can render a switcher over "the
 * transcripts in play" without knowing which kind of run produced each.
 * Workflow agents come back unresolved unless their run id is supplied — the
 * ref says so rather than guessing.
 */
export function collectTranscriptRefs(
  location: SessionLocation,
  runs: readonly {
    readonly kind: string
    readonly taskId: string | null
    readonly callId: string
    readonly label: string | null
    readonly phases: readonly { readonly agents: readonly { readonly agentId: string | null; readonly label: string; readonly index: number }[] }[]
  }[],
  /** Workflow run ids by the `task_id` the stream reported, when the host has read the records. */
  runIdByTaskId: ReadonlyMap<string, string> = new Map(),
): readonly TranscriptRef[] {
  const refs: TranscriptRef[] = [
    {
      kind: "session",
      label: "Main conversation",
      key: location.sessionId,
      callId: null,
      path: sessionTranscriptPath(location),
      resolved: true,
      blockedBy: null,
    },
  ]

  for (const run of runs) {
    if (run.kind === "workflow") {
      const runId = run.taskId === null ? null : (runIdByTaskId.get(run.taskId) ?? null)
      for (const phase of run.phases) {
        for (const agent of phase.agents) {
          refs.push(workflowAgentTranscriptRef(location, runId, agent, run.callId))
        }
      }
      continue
    }
    refs.push(subagentTranscriptRef(location, run))
  }

  return refs
}

/** @responsibility Re-exports everything specific to reading Codex, so a consumer takes the provider in one import. */

export {
  CODEX_EVENT_MAPPING,
  CODEX_FILE_CHANGE,
  CODEX_TASK_KIND,
  CODEX_TOOL_KIND,
  codexFileChange,
  codexMappingFor,
  codexPlanStatus,
  codexToolKind,
  codexWireKind,
  type CodexMappingEntry,
  type CodexWireKind,
} from "./mapping"
export {
  CODEX_CAPABILITY_METHODS,
  codexCapabilities,
  type CodexCapabilityMethod,
} from "./capabilities"
export { CodexStreamMapper, mapCodexStream } from "./mapper"
// The whole wire surface, so a consumer holding a `CodexWireEvent` can name
// every arm it narrows to. A hand-kept list drifts — this one already had.
export * from "./wire"

/** @responsibility Describes Codex's `exec --json` wire shapes and decodes one line into them without interpreting it. */

import { parseJsonLine } from "../json"
import type { JsonValue } from "../json"
import type { WireProvenance } from "../events"

/**
 * The build these shapes were read from.
 *
 * Codex publishes no version on its stream, so this constant is the only
 * record of which build the fixtures describe. `codex --version` is what a
 * maintainer compares it against.
 */
export const CODEX_WIRE_PROVENANCE: WireProvenance = Object.freeze({
  cli: "codex-cli",
  version: "0.144.1",
  command: "codex exec --json",
  capturedOn: "2026-08-29",
})

/** Re-exported so one import gives a consumer this wire's whole vocabulary. */
export type { JsonValue }

/**
 * The line kinds `codex exec --json` emits.
 *
 * Codex reports a thread of **items** rather than a stream of content blocks:
 * a line either moves the thread or the turn, or reports one item's lifecycle.
 * That is a smaller vocabulary than Claude Code's, and a flatter one — there is
 * no separate system channel and no SSE frame layer.
 */
export const CodexWireType = Object.freeze({
  ThreadStarted: "thread.started",
  TurnStarted: "turn.started",
  TurnCompleted: "turn.completed",
  TurnFailed: "turn.failed",
  ItemStarted: "item.started",
  ItemUpdated: "item.updated",
  ItemCompleted: "item.completed",
  Error: "error",
} as const)

export type CodexWireType = (typeof CodexWireType)[keyof typeof CodexWireType]

/**
 * The item kinds observed on the wire.
 *
 * A checklist of what is handled, never a claim about what exists: Codex adds
 * item kinds between releases, and anything unlisted must still reach the log
 * as an unknown event rather than failing the line.
 */
export const CodexItemType = Object.freeze({
  AgentMessage: "agent_message",
  Reasoning: "reasoning",
  CommandExecution: "command_execution",
  FileChange: "file_change",
  TodoList: "todo_list",
  WebSearch: "web_search",
  McpToolCall: "mcp_tool_call",
  /** Delegation: `spawn_agent` and friends, addressed by thread id rather than call id. */
  CollabToolCall: "collab_tool_call",
  Error: "error",
} as const)

export type CodexItemType = (typeof CodexItemType)[keyof typeof CodexItemType]

/**
 * An item's lifecycle status.
 *
 * Carried on the item rather than implied by the line kind, so a completed line
 * can still report a failure — which is how a non-zero command reports itself.
 */
export const CodexItemStatus = Object.freeze({
  InProgress: "in_progress",
  Completed: "completed",
  Failed: "failed",
} as const)

export type CodexItemStatus = (typeof CodexItemStatus)[keyof typeof CodexItemStatus]

/** How a file changed, as `file_change.changes[].kind` reports it. */
export const CodexFileChangeKind = Object.freeze({
  Add: "add",
  Update: "update",
  Delete: "delete",
  Rename: "rename",
} as const)

export type CodexFileChangeKind = (typeof CodexFileChangeKind)[keyof typeof CodexFileChangeKind]

/**
 * The collab tool that opens a delegated run.
 *
 * Other collab tools — `wait` — act on a run that already exists, so only this
 * one starts a task; treating them all as spawns makes one agent look like two.
 */
export const CODEX_SPAWN_TOOL = "spawn_agent"

/**
 * Codex's token accounting, as carried on `turn.completed`.
 *
 * Every field is optional: the counters are a different set from Anthropic's —
 * `cached_input_tokens` rather than a cache read/creation split, plus a
 * reasoning count that has no Claude counterpart — and a parser that assumes
 * any of them is present reports a confident zero for a turn that said nothing.
 */
export interface CodexUsage {
  readonly input_tokens?: number
  readonly cached_input_tokens?: number
  readonly output_tokens?: number
  readonly reasoning_output_tokens?: number
}

/**
 * The shapes below describe the wire; they do not police it.
 *
 * A declared type is a claim about bytes, not a check on them, so the mapper
 * still reads every field through the shared readers rather than trusting these
 * — see `json.ts`. What they buy is a reader's map of what a line can contain,
 * autocomplete while writing a consumer, and one place to update when the CLI
 * moves. Every union keeps an open arm for the same reason the vocabularies are
 * checklists: a kind from a later release must still parse.
 */

/** One file an agent touched, as `file_change.changes[]` reports it. */
export interface CodexFileChangeEntry {
  readonly path: string
  readonly kind: CodexFileChangeKind | string
  /** Present only when the agent supplies one; Codex reports paths, not text. */
  readonly diff?: string
}

/** One step of `todo_list.items[]`. A boolean, not a three-state status. */
export interface CodexTodoItem {
  readonly text: string
  readonly completed: boolean
}

/** Fields every item carries. */
interface CodexItemBase {
  readonly id: string
  readonly status?: CodexItemStatus | string
}

/** Committed prose from the agent. Codex sends no partial text in this mode. */
export interface CodexAgentMessageItem extends CodexItemBase {
  readonly type: "agent_message"
  readonly text: string
}

/** Committed reasoning. */
export interface CodexReasoningItem extends CodexItemBase {
  readonly type: "reasoning"
  readonly text?: string
  readonly summary?: readonly JsonValue[]
  readonly content?: readonly JsonValue[]
}

/**
 * A shell command.
 *
 * Richer than Claude's tool result: the exit code is reported, so failure is a
 * fact the wire states rather than something inferred from output prose.
 */
export interface CodexCommandExecutionItem extends CodexItemBase {
  readonly type: "command_execution"
  readonly command: string
  readonly aggregated_output?: string
  readonly exit_code?: number | null
  readonly cwd?: string
}

/** Structured edits — which files changed and how. Claude Code reports no equivalent. */
export interface CodexFileChangeItem extends CodexItemBase {
  readonly type: "file_change"
  readonly changes: readonly CodexFileChangeEntry[]
}

/** The plan, republished whole on every update. Steps have no ids; position is identity. */
export interface CodexTodoListItem extends CodexItemBase {
  readonly type: "todo_list"
  readonly items: readonly CodexTodoItem[]
}

export interface CodexWebSearchItem extends CodexItemBase {
  readonly type: "web_search"
  readonly query?: string
  readonly action?: JsonValue
}

export interface CodexMcpToolCallItem extends CodexItemBase {
  readonly type: "mcp_tool_call"
  readonly tool?: string
  readonly server?: string
  readonly result?: JsonValue
}

/**
 * Delegation.
 *
 * The spawned agent writes nothing to this stream: `receiver_thread_ids` is the
 * address of its own transcript, and `agents_states` is the only live signal
 * the parent gets about it.
 */
export interface CodexCollabToolCallItem extends CodexItemBase {
  readonly type: "collab_tool_call"
  readonly tool?: string
  readonly prompt?: string | null
  readonly sender_thread_id?: string
  readonly receiver_thread_ids?: readonly string[]
  readonly agents_states?: Readonly<Record<string, JsonValue>>
}

export interface CodexErrorItem extends CodexItemBase {
  readonly type: "error"
  readonly message?: string
}

/** An item kind this build does not model. Kept open so a later release still parses. */
export interface CodexUnknownItem extends CodexItemBase {
  readonly type: string
  readonly [key: string]: JsonValue | undefined
}

/** Everything an `item.*` line can carry. */
export type CodexItem =
  | CodexAgentMessageItem
  | CodexReasoningItem
  | CodexCommandExecutionItem
  | CodexFileChangeItem
  | CodexTodoListItem
  | CodexWebSearchItem
  | CodexMcpToolCallItem
  | CodexCollabToolCallItem
  | CodexErrorItem
  | CodexUnknownItem

/** Opens the thread and names it. A resume reuses the same id and says nothing else. */
export interface CodexThreadStartedLine {
  readonly type: "thread.started"
  readonly thread_id: string
}

/** A bare marker; the turn's own items say everything it does. */
export interface CodexTurnStartedLine {
  readonly type: "turn.started"
}

/** The turn terminator, carrying usage. */
export interface CodexTurnCompletedLine {
  readonly type: "turn.completed"
  readonly usage?: CodexUsage
  readonly duration_ms?: number
}

export interface CodexTurnFailedLine {
  readonly type: "turn.failed"
  readonly error?: { readonly message?: string }
  readonly usage?: CodexUsage
}

/** An item opening, changing, or settling. The item's own `id` is the call id. */
export interface CodexItemLine {
  readonly type: "item.started" | "item.updated" | "item.completed"
  readonly item: CodexItem
}

/** A thread-level failure outside any item. */
export interface CodexErrorLine {
  readonly type: "error"
  readonly message?: string
}

/** Any decoded line, before anything past `type` has been checked. */
export interface CodexRawLine {
  readonly type: string
  readonly [key: string]: JsonValue | undefined
}

/** A line kind this build does not model. */
export interface CodexUnknownLine {
  readonly type: string
  readonly [key: string]: JsonValue | undefined
}

/** One decoded line. */
export type CodexWireEvent =
  | CodexThreadStartedLine
  | CodexTurnStartedLine
  | CodexTurnCompletedLine
  | CodexTurnFailedLine
  | CodexItemLine
  | CodexErrorLine
  | CodexUnknownLine

export interface CodexParseFailure {
  readonly ok: false
  readonly line: string
  readonly reason: string
}

export interface CodexParseSuccess {
  readonly ok: true
  /**
   * What the parser actually verified: an object with a string `type`.
   *
   * Not one of the arms above. Returning the union would claim
   * `thread_id`, `item.id` and the rest are present when nothing checked
   * them — and a consumer trusting that claim reads `undefined` from a field
   * typed `string`. The arms stay exported as a description of the wire; a
   * consumer that wants one narrows to it after checking, the way this
   * package's own mapper does.
   */
  readonly line: CodexRawLine
}

export type CodexParseResult = CodexParseSuccess | CodexParseFailure

/**
 * Decodes one line of `codex exec --json`.
 *
 * Failure is returned rather than thrown, for the reason the Claude wire gives:
 * a stream is read for as long as the process runs, and one malformed line must
 * not end the transcript.
 */
/**
 * Decodes one line of Codex's stream.
 *
 * The decoding itself is shared — every provider's wire is newline-delimited
 * JSON, and one copy per provider is one place per provider for a bug in it to
 * live. What stays here is the naming and the return type.
 */
export function parseCodexLine(line: string): CodexParseResult {
  const result = parseJsonLine(line)
  return result.ok ? { ok: true, line: result.line as CodexRawLine } : result
}

/** Decodes a whole capture, keeping failures in place. */
export function parseCodexLines(text: string): readonly CodexParseResult[] {
  return text
    .split("\n")
    .filter((line) => line.trim().length > 0)
    .map(parseCodexLine)
}

/** @responsibility States, as data, which Codex line kind becomes which normalized event. */

import { AgentEventType, FileChange, PlanStepStatus, TaskKind, ToolKind } from "../events"
import { asRecord, asString } from "../json"
import type { JsonValue } from "../json"
import { CodexFileChangeKind, CodexItemType, CodexWireType } from "./wire"
import type { CodexRawLine } from "./wire"

/** A line's kind at the granularity the mapping turns on: the line type, plus the item kind where there is one. */
export type CodexWireKind = string

export interface CodexMappingEntry {
  /** The normalized events this kind can produce. Empty means it deliberately produces nothing. */
  readonly emits: readonly AgentEventType[]
  /** Why, in one line. For an empty `emits` this is the whole justification. */
  readonly note: string
}

/**
 * The provider-to-contract mapping, as data.
 *
 * The same shape `CLAUDE_EVENT_MAPPING` uses, against the same
 * [`AgentEventType`] values — which is what makes "swap the mapper, keep the
 * components" checkable rather than aspirational. A kind missing from here is a
 * line nobody decided about.
 */
export const CODEX_EVENT_MAPPING: Readonly<Record<CodexWireKind, CodexMappingEntry>> = Object.freeze({
  [CodexWireType.ThreadStarted]: {
    emits: [AgentEventType.SessionStarted],
    note: "opens the thread and names it; a resume reuses the same thread id",
  },
  [CodexWireType.TurnStarted]: {
    emits: [],
    note: "a bare marker carrying nothing the turn's own events do not already say",
  },
  [CodexWireType.TurnCompleted]: {
    emits: [AgentEventType.TurnCompleted],
    note: "the turn terminator, carrying usage",
  },
  [CodexWireType.TurnFailed]: {
    emits: [AgentEventType.TurnCompleted],
    note: "the same terminator with an error status",
  },
  [CodexWireType.Error]: {
    emits: [AgentEventType.Error],
    note: "a thread-level failure outside any item",
  },

  // ---------- conversation ----------
  [`${CodexWireType.ItemCompleted}/${CodexItemType.AgentMessage}`]: {
    emits: [AgentEventType.AssistantText],
    note: "committed prose; Codex does not stream it in this mode, so there is no preview to supersede",
  },
  [`${CodexWireType.ItemStarted}/${CodexItemType.AgentMessage}`]: {
    emits: [],
    note: "the message is reported whole on completion",
  },
  [`${CodexWireType.ItemCompleted}/${CodexItemType.Reasoning}`]: {
    emits: [AgentEventType.Reasoning],
    note: "committed reasoning",
  },
  [`${CodexWireType.ItemStarted}/${CodexItemType.Reasoning}`]: {
    emits: [],
    note: "reported whole on completion",
  },

  // ---------- tools ----------
  [`${CodexWireType.ItemUpdated}/${CodexItemType.CommandExecution}`]: {
    emits: [],
    note: "incremental output on a long command; the completion carries the whole of it, so a partial adds nothing a consumer can use yet",
  },
  [`${CodexWireType.ItemUpdated}/${CodexItemType.AgentMessage}`]: {
    emits: [],
    note: "the message is reported whole on completion",
  },
  [`${CodexWireType.ItemUpdated}/${CodexItemType.Reasoning}`]: {
    emits: [],
    note: "reported whole on completion",
  },
  [`${CodexWireType.ItemUpdated}/${CodexItemType.FileChange}`]: {
    emits: [],
    note: "the completion publishes the paths",
  },
  [`${CodexWireType.ItemUpdated}/${CodexItemType.WebSearch}`]: {
    emits: [],
    note: "the completion settles the search",
  },
  [`${CodexWireType.ItemUpdated}/${CodexItemType.CollabToolCall}`]: {
    emits: [AgentEventType.TaskCompleted],
    note: "a live agents_states update; a terminal state closes the run the spawn opened",
  },
  [`${CodexWireType.ItemStarted}/${CodexItemType.CommandExecution}`]: {
    emits: [AgentEventType.ToolCallStarted],
    note: "a shell command begins; the item id is the call id",
  },
  [`${CodexWireType.ItemCompleted}/${CodexItemType.CommandExecution}`]: {
    emits: [AgentEventType.ToolCallCompleted],
    note: "output and exit code, which Codex reports where Claude sends only text",
  },
  [`${CodexWireType.ItemStarted}/${CodexItemType.WebSearch}`]: {
    emits: [AgentEventType.ToolCallStarted],
    note: "a search begins",
  },
  [`${CodexWireType.ItemCompleted}/${CodexItemType.WebSearch}`]: {
    emits: [AgentEventType.ToolCallCompleted],
    note: "the search settles",
  },
  [`${CodexWireType.ItemStarted}/${CodexItemType.McpToolCall}`]: {
    emits: [AgentEventType.ToolCallStarted],
    note: "an MCP tool call begins",
  },
  [`${CodexWireType.ItemCompleted}/${CodexItemType.McpToolCall}`]: {
    emits: [AgentEventType.ToolCallCompleted],
    note: "the MCP tool call settles",
  },

  // ---------- file changes ----------
  [`${CodexWireType.ItemStarted}/${CodexItemType.FileChange}`]: {
    emits: [AgentEventType.ToolCallStarted],
    note: "an edit begins; the paths are known up front",
  },
  [`${CodexWireType.ItemCompleted}/${CodexItemType.FileChange}`]: {
    emits: [AgentEventType.ToolCallCompleted, AgentEventType.FileEdits],
    note: "structured edits, which Claude Code does not report at all — the call settles and the paths are published",
  },

  // ---------- plan ----------
  [`${CodexWireType.ItemStarted}/${CodexItemType.TodoList}`]: {
    emits: [AgentEventType.PlanUpdated],
    note: "the plan republished whole, the shape TodoWrite used",
  },
  [`${CodexWireType.ItemUpdated}/${CodexItemType.TodoList}`]: {
    emits: [AgentEventType.PlanUpdated],
    note: "republished again as steps complete; latest wins",
  },
  [`${CodexWireType.ItemCompleted}/${CodexItemType.TodoList}`]: {
    emits: [AgentEventType.PlanUpdated],
    note: "the final state of the plan",
  },

  // ---------- delegation ----------
  [`${CodexWireType.ItemStarted}/${CodexItemType.CollabToolCall}`]: {
    emits: [AgentEventType.ToolCallStarted, AgentEventType.TaskStarted],
    note: "a spawned agent: a call on this thread, and a run whose own work never reaches this stream",
  },
  [`${CodexWireType.ItemCompleted}/${CodexItemType.CollabToolCall}`]: {
    emits: [AgentEventType.ToolCallCompleted, AgentEventType.TaskCompleted],
    note: "the spawn settles and names the receiver threads, which is where the run's transcript lives",
  },

  // ---------- fallback ----------
  [`${CodexWireType.ItemCompleted}/${CodexItemType.Error}`]: {
    emits: [AgentEventType.Error],
    note: "an item-level failure",
  },
})

/** The mapping key for one decoded line. */
export function codexWireKind(event: CodexRawLine): CodexWireKind {
  const line = asRecord(event as JsonValue)
  const type = asString(line.type) ?? "unknown"
  const item = asRecord(line.item)
  const itemType = asString(item.type)
  return itemType === null ? type : `${type}/${itemType}`
}

/** What a line kind is declared to produce, or null for a kind nobody has decided about. */
export function codexMappingFor(kind: CodexWireKind): CodexMappingEntry | null {
  return CODEX_EVENT_MAPPING[kind] ?? null
}

/**
 * Codex's item kinds mapped to our tool rendering hints.
 *
 * A lookup rather than a chain of comparisons, for the reason the Claude table
 * gives: the mapping is data, and written as data the compiler checks it
 * against the provider's own union.
 */
export const CODEX_TOOL_KIND: Readonly<Partial<Record<CodexItemType, ToolKind>>> = Object.freeze({
  [CodexItemType.CommandExecution]: "shell",
  [CodexItemType.FileChange]: "file_edit",
  [CodexItemType.WebSearch]: "web",
  [CodexItemType.McpToolCall]: "mcp",
  [CodexItemType.CollabToolCall]: "subagent",
})

/** Reads an item kind as one of our tool kinds. */
export function codexToolKind(itemType: string | null): ToolKind {
  if (itemType === null) return "other"
  // Keyed by the provider's own union, so a renamed kind fails to compile
  // rather than silently rendering every call as "other".
  return CODEX_TOOL_KIND[itemType as CodexItemType] ?? "other"
}

/** Codex's file-change words, mapped to ours. */
export const CODEX_FILE_CHANGE: Readonly<Record<CodexFileChangeKind, FileChange>> = Object.freeze({
  [CodexFileChangeKind.Add]: "add",
  [CodexFileChangeKind.Update]: "update",
  [CodexFileChangeKind.Delete]: "delete",
  [CodexFileChangeKind.Rename]: "rename",
})

/** Reads a change kind as one of ours, defaulting to an update. */
export function codexFileChange(kind: string | null): FileChange {
  if (kind === null) return "update"
  return CODEX_FILE_CHANGE[kind as CodexFileChangeKind] ?? "update"
}

/** A todo item is a boolean here, not a three-state status; a run's current step is not distinguishable. */
export function codexPlanStatus(completed: boolean): PlanStepStatus {
  return completed ? PlanStepStatus.Completed : PlanStepStatus.Pending
}

/** Every Codex delegation is an agent run; it has no workflow or background-shell kind. */
export const CODEX_TASK_KIND: TaskKind = TaskKind.Agent

/** @responsibility Turns Codex `exec --json` lines into normalized agent events, holding the little state that requires. */

import type {
  AgentEvent,
  AgentEventPayload,
  AgentPath,
  AgentStreamMapper,
  FileEdit,
  MapperOptions,
  PlanStep,
  SessionInfo,
  ToolResult,
  Usage,
} from "../events"
import { asArray, asBoolean, asNumber, asObject, asRecord, asString, asStrings, shortenPath } from "../json"
import type { JsonValue } from "../json"
import {
  CODEX_TASK_KIND,
  codexFileChange,
  codexMappingFor,
  codexPlanStatus,
  codexToolKind,
} from "./mapping"
import { CODEX_SPAWN_TOOL, CodexItemStatus, CodexItemType, CodexWireType, parseCodexLine } from "./wire"
import type { CodexRawLine } from "./wire"

/** One line naming what an item does, from its own fields. */
function itemTitle(itemType: string, item: Record<string, JsonValue>): string {
  switch (itemType) {
    case CodexItemType.CommandExecution:
      return asString(item.command) ?? "command"
    case CodexItemType.FileChange: {
      const paths = readEdits(item).map((edit) => edit.path)
      if (paths.length === 0) return "file change"
      return paths.length === 1 ? shortenPath(paths[0]!) : `${paths.length} files`
    }
    case CodexItemType.WebSearch: {
      const query = asString(item.query)
      return query === null || query === "" ? "web search" : query
    }
    case CodexItemType.CollabToolCall:
      return asString(item.tool) ?? "spawn agent"
    case CodexItemType.McpToolCall:
      return asString(item.tool) ?? "mcp tool"
    default:
      return itemType
  }
}

/** Reads `file_change.changes[]` into the shared edit shape. */
function readEdits(item: Record<string, JsonValue>): readonly FileEdit[] {
  const edits: FileEdit[] = []
  for (const entry of asArray(item.changes)) {
    const change = asRecord(entry)
    const path = asString(change.path)
    if (path === null) continue
    edits.push({
      path,
      change: codexFileChange(asString(change.kind)),
      // Codex publishes which files changed and how, not the text of the
      // change; a consumer wanting a diff reads the file itself.
      unifiedDiff: asString(change.diff),
    })
  }
  return edits
}

/**
 * A call's arguments, as arguments.
 *
 * The item also carries its id, status and output; those describe the call's
 * lifecycle rather than what it was asked to do, and a drawer that prints them
 * as "input" is showing plumbing.
 */
function callInput(itemType: string, item: Record<string, JsonValue>): JsonValue {
  switch (itemType) {
    case CodexItemType.CommandExecution:
      return { command: item.command ?? null, cwd: item.cwd ?? null }
    case CodexItemType.FileChange:
      return { changes: item.changes ?? [] }
    case CodexItemType.WebSearch:
      return { query: item.query ?? null }
    case CodexItemType.CollabToolCall:
      return { tool: item.tool ?? null, prompt: item.prompt ?? null }
    case CodexItemType.McpToolCall:
      return { tool: item.tool ?? null, server: item.server ?? null }
    default:
      return {}
  }
}

/** Reads `todo_list.items[]` into plan steps. */
function readPlan(item: Record<string, JsonValue>): readonly PlanStep[] {
  const steps: PlanStep[] = []
  for (const entry of asArray(item.items)) {
    const todo = asRecord(entry)
    const content = asString(todo.text)
    if (content === null) continue
    steps.push({
      // Codex identifies a step by position in a republished list, so there is
      // no id to carry — and none is needed: the whole list arrives each time.
      id: null,
      content,
      status: codexPlanStatus(asBoolean(todo.completed) === true),
    })
  }
  return steps
}

/**
 * What an item handed back.
 *
 * Richer than Claude's tool results, which are flat text: a command reports its
 * own exit code, so failure is a fact rather than something inferred from
 * prose.
 */
function readResult(itemType: string, item: Record<string, JsonValue>): ToolResult {
  const status = asString(item.status)
  const exitCode = asNumber(item.exit_code)
  const failed = status === CodexItemStatus.Failed || (exitCode !== null && exitCode !== 0)

  // `structured` is the result's own extra detail, not the whole line — the
  // envelope's `raw` already keeps that, and duplicating it here makes tool
  // drawers print lifecycle plumbing as if it were output.
  if (itemType === CodexItemType.CommandExecution) {
    return {
      text: asString(item.aggregated_output) ?? "",
      isError: failed,
      structured: exitCode === null ? null : { exit_code: exitCode },
      images: [],
    }
  }
  if (itemType === CodexItemType.FileChange) {
    const edits = readEdits(item)
    return {
      text: edits.map((edit) => `${edit.change} ${edit.path}`).join("\n"),
      isError: failed,
      structured: { changes: item.changes ?? [] },
      images: [],
    }
  }
  if (itemType === CodexItemType.WebSearch) {
    // The wire reports no results for a search — only what was searched, and
    // only on completion (the started item's `query` is empty). That is not
    // output, so it stays out of `text` and goes where a drawer can show it.
    return { text: "", isError: failed, structured: { query: item.query ?? null }, images: [] }
  }
  return { text: "", isError: failed, structured: null, images: [] }
}

function normalizeUsage(usage: JsonValue | undefined): Usage | null {
  const fields = asObject(usage)
  if (fields === null) return null
  const input = asNumber(fields.input_tokens)
  const output = asNumber(fields.output_tokens)
  const cached = asNumber(fields.cached_input_tokens)
  // Reported separately here, and folded into output by Claude. Counted in the
  // total because Codex's `output_tokens` excludes it — a total without it
  // understates what the turn cost.
  const reasoning = asNumber(fields.reasoning_output_tokens)
  const counters = [input, output, reasoning].filter((count): count is number => count !== null)
  return {
    totalTokens: counters.length === 0 ? null : counters.reduce((sum, count) => sum + count, 0),
    inputTokens: input,
    outputTokens: output,
    // Codex reports one cached figure where Anthropic splits read from
    // creation; it is a read, and the creation side stays unknown rather than
    // becoming a zero nobody reported.
    cacheReadTokens: cached,
    cacheCreationTokens: null,
    reasoningTokens: reasoning,
  }
}

/**
 * Maps one Codex thread's stdout into normalized events.
 *
 * Far less stateful than the Claude mapper, because the wire is: items carry
 * their own ids and arrive whole, so there is no block index to derive and no
 * preview to join. What remains is the sequence, the thread's identity, and
 * which items are open.
 */
export class CodexStreamMapper implements AgentStreamMapper {
  private seq: number
  private threadId: string | null = null
  private session: SessionInfo | null = null
  /** How many `thread.started` lines this mapper has seen, for `SessionInfo.initIndex`. */
  private threadStarts = 0
  /**
   * Which spawn call owns each receiver thread.
   *
   * A delegated run is addressed by the thread it runs in, not by the call that
   * mentions it: `spawn_agent` starts it and a later `wait` reports its result,
   * and both are separate items. Without this the two become two runs for one
   * agent — the second labelled "wait", with no prompt and no output.
   */
  private readonly spawnOfThread = new Map<string, string>()

  constructor(options: MapperOptions = {}) {
    this.seq = options.startSeq ?? 0
  }

  /** Decodes and maps one line. An unreadable line becomes a single `error` event rather than nothing. */
  push(line: string): readonly AgentEvent[] {
    const parsed = parseCodexLine(line)
    if (!parsed.ok) {
      return [
        this.build({ type: "error", message: `unreadable line: ${parsed.reason}` }, [], { line: parsed.line }),
      ]
    }
    return this.map(parsed.line)
  }

  /** Maps an already-decoded line. */
  map(event: CodexRawLine): readonly AgentEvent[] {
    const raw = event as JsonValue
    const line = asRecord(raw)
    const type = asString(line.type) ?? "unknown"

    switch (type) {
      case CodexWireType.ThreadStarted: {
        const threadId = asString(line.thread_id)
        if (threadId === null) return []
        this.threadId = threadId
        // `thread.started` carries an id and nothing else — no model, no cwd,
        // no tool list. Those stay null rather than becoming "unknown": a
        // placeholder on screen states something the wire never did, and the
        // capability answers live on the app-server instead.
        const session: SessionInfo = {
          sessionId: threadId,
          model: null,
          cwd: null,
          tools: [],
          slashCommands: [],
          terminalSlashCommands: [],
          agents: [],
          skills: [],
          plugins: [],
          mcpServers: [],
          permissionMode: null,
          version: null,
          outputStyle: null,
          initIndex: this.threadStarts,
        }
        this.threadStarts += 1
        this.session = session
        return [this.build({ type: "session_started", session }, [], raw)]
      }

      // A bare marker: the turn's own events already say everything it does.
      case CodexWireType.TurnStarted:
        return []

      case CodexWireType.TurnCompleted:
      case CodexWireType.TurnFailed:
        return [
          this.build(
            {
              type: "turn_completed",
              status: type === CodexWireType.TurnFailed ? "error" : "completed",
              stopReason: null,
              terminalReason: asString(asRecord(line.error).message),
              // Codex sends no final-answer field; the last agent_message is
              // the answer, and the fold already falls back to it.
              finalText: null,
              usage: normalizeUsage(line.usage),
              durationMs: asNumber(line.duration_ms),
              numTurns: null,
              permissionDenials: [],
            },
            [],
            raw,
          ),
        ]

      case CodexWireType.ItemStarted:
      case CodexWireType.ItemUpdated:
      case CodexWireType.ItemCompleted:
        return this.mapItem(type, asRecord(line.item), raw)

      case CodexWireType.Error:
        return [this.build({ type: "error", message: asString(line.message) ?? "unknown error" }, [], raw)]

      default:
        return [this.build({ type: "unknown", wireType: type, subtype: null }, [], raw)]
    }
  }

  private mapItem(lineType: string, item: Record<string, JsonValue>, raw: JsonValue): readonly AgentEvent[] {
    const itemType = asString(item.type)
    const id = asString(item.id)
    if (itemType === null || id === null) {
      return [this.build({ type: "unknown", wireType: lineType, subtype: itemType }, [], raw)]
    }

    // The table is the authority on what a line kind produces, so it is
    // consulted for every kind rather than only for the ones the switch below
    // does not name — otherwise a kind the table has never heard of is handled
    // anyway and the table's word means nothing.
    if (codexMappingFor(`${lineType}/${itemType}`) === null) {
      return [this.build({ type: "unknown", wireType: lineType, subtype: itemType }, [], raw)]
    }

    const completed = lineType === CodexWireType.ItemCompleted
    const updated = lineType === CodexWireType.ItemUpdated
    const events: AgentEvent[] = []

    switch (itemType) {
      // ---------- conversation: reported whole, on completion ----------
      case CodexItemType.AgentMessage:
        if (!completed) return []
        return [this.build({ type: "assistant_text", text: asString(item.text) ?? "", block: null }, [], raw)]

      case CodexItemType.Reasoning:
        if (!completed) return []
        return [this.build({ type: "reasoning", text: asString(item.text) ?? "", block: null }, [], raw)]

      // ---------- the plan, republished whole every time ----------
      case CodexItemType.TodoList:
        return [this.build({ type: "plan_updated", steps: readPlan(item) }, [], raw)]

      // ---------- everything else is a call that opens and settles ----------
      default: {
        // A live update on a spawned agent closes the run when its state turns
        // terminal; every other update reports nothing the completion will not.
        if (updated) {
          return itemType === CodexItemType.CollabToolCall ? this.mapCollabCompletion(id, item, raw) : []
        }

        if (!completed) {
          events.push(
            this.build(
              {
                type: "tool_call_started",
                callId: id,
                name: itemType,
                kind: codexToolKind(itemType),
                input: callInput(itemType, item),
                title: itemTitle(itemType, item),
              },
              [],
              raw,
            ),
          )
          // A spawn is a run as well as a call, and the run's own work never
          // reaches this stream — the receiver thread is where it lives. Other
          // collab tools (`wait`) act on a run that already exists, so they
          // are a call and nothing more.
          if (itemType === CodexItemType.CollabToolCall && asString(item.tool) === CODEX_SPAWN_TOOL) {
            events.push(
              this.build(
                {
                  type: "task_started",
                  taskId: id,
                  callId: id,
                  taskKind: CODEX_TASK_KIND,
                  label: asString(item.tool),
                  description: asString(item.prompt) ?? "",
                  prompt: asString(item.prompt),
                  // Codex names the receiver thread but exposes no way to read
                  // it, so there is no transcript to point a consumer at.
                  transcriptId: null,
                },
                [],
                raw,
              ),
            )
          }
          return events
        }

        events.push(
          this.build({ type: "tool_call_completed", callId: id, result: readResult(itemType, item) }, [], raw),
        )

        if (itemType === CodexItemType.FileChange) {
          events.push(this.build({ type: "file_edits", callId: id, edits: readEdits(item) }, [], raw))
        }
        if (itemType === CodexItemType.CollabToolCall) {
          events.push(...this.mapCollabCompletion(id, item, raw))
        }
        return events
      }
    }
  }

  /**
   * What a settled collab call says about the runs it touches.
   *
   * `agents_states` is the only place a spawned agent's outcome appears on this
   * stream — a `wait` completing carries the agent's own final text there. It
   * is reported against the run the spawn opened, so one agent stays one run.
   */
  private mapCollabCompletion(
    id: string,
    item: Record<string, JsonValue>,
    raw: JsonValue,
  ): readonly AgentEvent[] {
    const isSpawn = asString(item.tool) === CODEX_SPAWN_TOOL
    if (isSpawn) {
      for (const thread of asStrings(item.receiver_thread_ids)) this.spawnOfThread.set(thread, id)
    }

    const states = asRecord(item.agents_states)
    const events: AgentEvent[] = []
    for (const [thread, value] of Object.entries(states)) {
      const state = asRecord(value)
      const status = asString(state.status) ?? "unknown"
      // A run reported as still starting is not a completion; only a terminal
      // state closes it, and the message is what it produced.
      if (status === "pending_init" || status === "in_progress") continue
      events.push(
        this.build(
          {
            type: "task_completed",
            taskId: this.spawnOfThread.get(thread) ?? thread,
            callId: this.spawnOfThread.get(thread) ?? null,
            status,
            summary: asString(state.message),
            usage: null,
          },
          [],
          raw,
        ),
      )
    }

    // A spawn that named threads but reported no state yet has still opened the
    // run; nothing to close, so nothing is emitted.
    return events
  }

  private build(payload: AgentEventPayload, path: AgentPath, raw: JsonValue): AgentEvent {
    const seq = this.seq
    this.seq += 1
    const sessionId = this.threadId ?? this.session?.sessionId ?? "unknown"
    return { id: `${sessionId}:${seq}`, sessionId, seq, ts: null, agentPath: path, payload, raw }
  }
}

/** Maps a whole capture in one pass, for a persisted log or a fixture. */
export function mapCodexStream(text: string, options?: MapperOptions): readonly AgentEvent[] {
  const mapper = new CodexStreamMapper(options)
  const events: AgentEvent[] = []
  for (const line of text.split("\n")) {
    if (line.trim().length === 0) continue
    events.push(...mapper.push(line))
  }
  return events
}

/** @responsibility Describes what a session can do, in one shape every provider fills as much of as its wire allows. */

import type { ToolKind } from "./events"

/**
 * What a session advertises about itself.
 *
 * One shape rather than one per provider, for the reason the event contract is
 * shared: a composer's pickers should be written once. **Null means "this
 * provider cannot report it"** — never "none exist" — so a surface can omit a
 * section rather than render an empty one, and adding a provider does not add a
 * branch to the consumer.
 *
 * Where the answer comes from is each provider's business. Claude Code
 * advertises itself on its event stream; Codex answers a separate interactive
 * channel. Both end here.
 */
export interface AgentCapabilities {
  readonly sessionId: string | null
  readonly model: string | null
  readonly cwd: string | null
  readonly permissionMode: string | null
  /** Models the session could switch to. */
  readonly models: readonly CapabilityModel[] | null
  /** Slash commands, whatever supplies them. */
  readonly commands: readonly CapabilityCommand[] | null
  readonly skills: readonly CapabilitySkill[] | null
  /** Delegated agents that can be spawned by name. */
  readonly agents: readonly string[] | null
  readonly tools: readonly CapabilityTool[] | null
  readonly mcpServers: readonly CapabilityServer[] | null
  /** Plugins installed into this session. */
  readonly plugins: readonly CapabilityPlugin[] | null
  /** Catalogues a plugin could be installed from, which a picker searches rather than lists. */
  readonly pluginSources: readonly CapabilityPluginSource[] | null
  readonly hooks: readonly CapabilityHook[] | null
}

/** Where a slash command comes from, which is what a picker groups by. */
export type CommandSource = "skill" | "plugin" | "session" | "terminal"

export interface CapabilityCommand {
  /** As typed, without the leading slash. */
  readonly name: string
  readonly source: CommandSource
  /** The plugin that supplies it, for a `plugin:command` name. */
  readonly plugin: string | null
}

export interface CapabilityModel {
  readonly id: string
  readonly label: string
  readonly description: string | null
  readonly isDefault: boolean
}

export interface CapabilitySkill {
  readonly name: string
  readonly description: string | null
}

export interface CapabilityTool {
  readonly name: string
  readonly kind: ToolKind
  /** The MCP server that supplies it, where the name says so. */
  readonly server: string | null
  /**
   * True when the tool was absent from the session's first advertisement and
   * appeared later — which is what a deferred tool loading on demand looks
   * like from outside.
   */
  readonly deferred: boolean
}

export interface CapabilityServer {
  readonly name: string
  readonly status: string
  /** The only status that means the tools are usable now. */
  readonly connected: boolean
  readonly tools: readonly string[]
}

export interface CapabilityPlugin {
  readonly name: string
  readonly version: string | null
  readonly source: string | null
}

export interface CapabilityPluginSource {
  readonly name: string
  /** The catalogue's real size, which can be far larger than what a reply carried. */
  readonly count: number
  /** What the reply actually returned, when it returned a sample. */
  readonly sample: readonly string[]
}

export interface CapabilityHook {
  readonly event: string | null
  readonly source: string | null
}

/** Every section a provider left unreported, for a surface that wants to say so. */
export function unreportedCapabilities(capabilities: AgentCapabilities): readonly string[] {
  const sections: readonly (readonly [string, unknown])[] = [
    ["models", capabilities.models],
    ["commands", capabilities.commands],
    ["skills", capabilities.skills],
    ["agents", capabilities.agents],
    ["tools", capabilities.tools],
    ["MCP servers", capabilities.mcpServers],
    ["plugins", capabilities.plugins],
    ["plugin sources", capabilities.pluginSources],
    ["hooks", capabilities.hooks],
  ]
  return sections.filter(([, value]) => value === null).map(([name]) => name)
}

/** @responsibility Reads what a Codex session can do from the app-server, which is the only place that answers. */

import type {
  AgentCapabilities,
  CapabilityHook,
  CapabilityModel,
  CapabilityPluginSource,
  CapabilitySkill,
} from "../capabilities"
import { asArray, asNumber, asRecord, asString } from "../json"
import type { JsonValue } from "../json"

/**
 * Codex reports capabilities on a different channel from its stream.
 *
 * `codex exec --json` opens with a thread id and nothing else — no model list,
 * no skills, no plugins — so a composer built on that stream has nothing to
 * populate its pickers with. The interactive `codex app-server` answers
 * `model/list`, `skills/list`, `plugin/list` and `hooks/list` on request.
 *
 * This module reads those replies. It does **not** speak to the app-server:
 * holding that connection is a host's job, and this stays a pure function over
 * whatever the host got back — which is also what makes it testable against a
 * captured reply.
 */



/** The app-server methods this reads, so a host knows what to ask for. */
export const CODEX_CAPABILITY_METHODS = Object.freeze([
  "model/list",
  "skills/list",
  "plugin/list",
  "hooks/list",
] as const)

export type CodexCapabilityMethod = (typeof CODEX_CAPABILITY_METHODS)[number]

/**
 * Reads the app-server's replies, keyed by the method that produced each.
 *
 * A missing method reads as an empty list rather than an error: a host may ask
 * for only what a surface needs, and a picker with no plugins is a picker, not
 * a failure.
 */
export function codexCapabilities(replies: Readonly<Record<string, JsonValue>>): AgentCapabilities {
  const models: CapabilityModel[] = []
  for (const entry of asArray(asRecord(replies["model/list"]).data)) {
    const model = asRecord(entry)
    const id = asString(model.id)
    if (id === null) continue
    models.push({
      id,
      label: asString(model.displayName) ?? id,
      description: asString(model.description),
      isDefault: model.isDefault === true,
    })
  }

  // Skills and hooks are reported per working directory, since both can be
  // defined by the project as well as the user.
  const skills: CapabilitySkill[] = []
  for (const scope of asArray(asRecord(replies["skills/list"]).data)) {
    for (const entry of asArray(asRecord(scope).skills)) {
      const skill = asRecord(entry)
      const name = asString(skill.name)
      if (name === null) continue
      skills.push({ name, description: asString(skill.description) })
    }
  }

  const hooks: CapabilityHook[] = []
  for (const scope of asArray(asRecord(replies["hooks/list"]).data)) {
    for (const entry of asArray(asRecord(scope).hooks)) {
      const hook = asRecord(entry)
      // The reply names these `eventName` and `sourcePath`; `source` beside
      // them is the *kind* of source ("plugin"), not where it came from, so
      // reading it as the location returns the same word for every hook.
      hooks.push({ event: asString(hook.eventName), source: asString(hook.sourcePath) })
    }
  }

  const pluginSources: CapabilityPluginSource[] = []
  for (const entry of asArray(asRecord(replies["plugin/list"]).marketplaces)) {
    const marketplace = asRecord(entry)
    const name = asString(marketplace.name)
    if (name === null) continue
    const sample = asArray(marketplace.plugins)
      .map((plugin) => asString(asRecord(plugin).name) ?? asString(asRecord(plugin).id))
      .filter((name): name is string => name !== null)
    pluginSources.push({
      name,
      // The reply carries the true size when the sample is trimmed; without it
      // the sample's length is the best available answer.
      count: asNumber(marketplace.pluginCount) ?? sample.length,
      sample,
    })
  }

  return {
    // The app-server answers about the installation, not about one thread, so
    // the session's own identity is not part of this reply.
    sessionId: null,
    model: null,
    cwd: null,
    permissionMode: null,
    models,
    skills,
    hooks,
    pluginSources,
    // Null rather than empty: Codex has these concepts, this reply does not
    // carry them, and a picker should omit the section rather than show it bare.
    commands: null,
    agents: null,
    tools: null,
    mcpServers: null,
    plugins: null,
  }
}
